/* DAWAH X — ahmad, অধ্যায় 46 · খণ্ড 46 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][46]=[[9001,9001,"","ঈশ্বর বলে দেবেন, যদি আমি তোমাকে খেতে দিই ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ يَعْنِي ابْنَ عُرْوَةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَكَلَ أَحَدُكُمْ فَلْيَلْعَقْ أَصَابِعَهُ فَإِنَّهُ لَا يَدْرِي فِي أَيِّ ذَلِكَ الْبَرَكَةُ ‏","","",""],[9002,9002,"","আমরা একটি নির্দিষ্ট ছেলের কথা বলেছিলাম যে তার বাবার কথা শুনে দেবীর মতো, পাহাড় বিয়ারের দ্বারা টেনে নিয়ে যায় আর বিয়ারের দ্বারাও ভাল আর পঞ্চমটা পরিবেশন করা হয়। আমরা চেষ্টা করেছি আমাদের পরীক্ষা করা হয়েছে। আমার বাবাকে যে কথা বলেছে, তা হল আমার বাবার জন্য কীভাবে দোষ দেওয়া যায়, সে তার স্তম্ভ পরিবর্তন করে বলেছিল ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْعَجْمَاءُ ‏ ‏جَرْحُهَا ‏ ‏جُبَارٌ ‏ ‏وَالْمَعْدِنُ ‏ ‏جُبَارٌ ‏ ‏وَالْبِئْرُ ‏ ‏جُبَارٌ ‏ ‏وَفِي ‏ ‏الرِّكَازِ ‏ ‏الْخُمْسُ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَ هَذَا غَيْرَ أَنَّهُ قَالَ ‏ ‏الرَّكَائِزُ ‏","","",""],[9003,9003,"","আমরা শপথ নিয়ে কথা বলেছি, আমরা ভালো যোদ্ধার সাথে আমার বাবার সাথে কথা বলব, সে ঈশ্বরের কাছে প্রার্থনা করছে যেন সে আগুনের আগুনে হাত দেয় এবং ভালবাসার পথ খুলে দেয়।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏الْقَاسِمُ بْنُ الْفَضْلِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ الْمَهْرِيِّ ‏ ‏قَالَ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏يَا مَهْرِيُّ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ثَمَنِ الْكَلْبِ وَكَسْبِ ‏ ‏الْمُومِسَةِ ‏ ‏وَكَسْبِ الْحَجَّامِ ‏ ‏وَكَسْبِ ‏ ‏عَسِيبِ ‏ ‏الْفَحْلِ ‏","","",""],[9004,9004,"","আমরা ঈশ্বরের গিল্ডের কথা শুনেছি, আমার বাবা একটা ঘোড়া যোগ করে বলবে সে বলবে সে ঈশ্বরের প্রভু। তাদের আবেগ ছিলো, আমার কনফিউজিং করতে চাই।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْعَبَّاسُ الْجُرَيْرِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا عُثْمَانَ النَّهْدِيَّ ‏ ‏يَقُولُ ‏ ‏تَضَيَّفْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏سَبْعًا قَالَ وَسَمِعْتُهُ يَقُولُ ‏ ‏قَسَمَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ أَصْحَابِهِ تَمْرًا فَأَصَابَنِي سَبْعُ تَمَرَاتٍ إِحْدَاهُنَّ ‏ ‏حَشَفَةٌ ‏ ‏فَلَمْ يَكُنْ شَيْءٌ ‏ ‏أَعْجَبَ ‏ ‏إِلَيَّ مِنْهَا شَدَّتْ ‏ ‏مَضَاغِي ‏","","",""],[9005,9005,"","আমরা আমার বাবার কথা বলেছিলাম যে আমাদের একজন পলাতকের কথা, যে আমাদের ঈশ্বরের কাছে প্রার্থনা করবে। তাকে আত্মসমর্পণ করতে হবে। সে প্রার্থনা করতে থাকবে না। প্রার্থনা করো, আশীর্বাদটা তার নিজের স্বার্থের সাথে পূর্ণ হোক, এমনকি চলে যাও, আমি বলছি যা হয় তা হলো, নাকি আঘাত লেগেছে, নাকি আঘাত পেয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَزَالُ الْعَبْدُ فِي صَلَاةٍ مَا كَانَ فِي مُصَلَّاهُ يَنْتَظِرُ الصَّلَاةَ تَقُولُ الْمَلَائِكَةُ اللَّهُمَّ اغْفِرْ لَهُ اللَّهُمَّ ارْحَمْهُ حَتَّى يَنْصَرِفَ أَوْ يُحْدِثَ قُلْتُ وَمَا يُحْدِثُ قَالَ ‏ ‏يَفْسُو أَوْ يَضْرِطُ ‏","","",""],[9006,9006,"","আমরা আমাদের বাপ্তিস্মকে রক্ষা করার চেষ্টা করেছি, আমরা বলেছিলাম যে, আমাদের মধ্যে আমার আকাঙ্ক্ষার জন্য একটা ভালো হাত ছিল। লর্ড তার জন্য প্রার্থনা করেছিল এবং তাকে আবার প্রবেশ করতে হবে এবং সে সেখানে প্রবেশ করবে অজাতের আনন্দ আবার, সে সাত বছরের ছাগল বানিয়ে সাত-আট-আট-আধক স্টান্টের মধ্যে দিয়ে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَدْخُلُ أَهْلُ الْجَنَّةِ ‏ ‏مُرْدًا ‏ ‏بِيضًا ‏ ‏جِعَادًا ‏ ‏مُكَحَّلِينَ أَبْنَاءَ ثَلَاثٍ وَثَلَاثِينَ عَلَى خَلْقِ ‏ ‏آدَمَ ‏ ‏سَبْعِينَ ذِرَاعًا فِي سَبْعَةِ أَذْرُعٍ ‏","","",""],[9007,9007,"","আমরা আমাদের বাপ্তিস্মকে রক্ষা করার চেষ্টা করেছি... ...এটা বলার মাধ্যমে যে আমরা একটা ঘোড়া শুনেছি, ঈশ্বরের কাছে প্রার্থনা করছি, আর আমি বলবো হরিণের দেখা পাওয়া যাবে আর তোমার আত্মাও নষ্ট হয়ে যাবে তাকে দেখতে এবং তার আত্মাকে দেখতে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏صُومُوا الْهِلَالَ لِرُؤْيَتِهِ وَأَفْطِرُوا لِرُؤْيَتِهِ فَإِنْ ‏ ‏غُمَّ ‏ ‏عَلَيْكُمْ فَعُدُّوا ثَلَاثِينَ ‏","","",""],[9008,9008,"","আমরা আমার বাবার কথা বলেছিলাম, তাকে আমার ছেলেকে খুঁজতে হবে, তাকে এক এক এক দিনের মধ্যে এবং আরো সাত দিনের খাবার খেতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمُؤْمِنُ يَأْكُلُ فِي مِعًى وَاحِدٍ وَالْكَافِرُ يَأْكُلُ فِي سَبْعَةِ أَمْعَاءٍ ‏","","",""],[9009,9009,"","আমরা একটা কথা বলেছি কিন্তু অফিসারদের মধ্যে সেরা। আমি এমন একজন লোক যে একটি দেওয়াল অতিক্রম করেছে। আমরা এ নিয়ে কথা বলেছি। ঈশ্বরের ইচ্ছা, আমি যে কোন বন্ধু ছাড়া আমি বেশি কিছু বিশ্বাস করি না। আমি যদি বলি, তাহলে আমি আপনাকে এই বিষয়ে কথা বলি, আমি আপনাকে বলতে পারি। আমি কি বলছি, আমি জানি, আমি কি বলছি, আমি কি বলছি, আমি জানি, আমি কি বলছি, আমি কি বলেছি? তুমি ব্যর্থতার প্রতি গভীর ভয় আর আত্মার ক্ষতি, এই ভাস্কর্যটা দুই বছর ধরে বলা হয়েছে যেন এটা একটা জিনিস।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُمَارَةُ بْنُ الْقَعْقَاعِ بْنِ شُبْرُمَةَ الضَّبِّيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو زُرْعَةَ بْنُ عَمْرِو بْنِ جَرِيرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ أَيُّ ‏ ‏الصَّدَقَةِ ‏ ‏أَعْظَمُ قَالَ ‏ ‏أَنْ تَتَصَدَّقَ وَأَنْتَ صَحِيحٌ ‏ ‏شَحِيحٌ ‏ ‏تَخْشَى الْفَقْرَ وَتَأْمُلُ الْبَقَاءَ وَلَا تَمَهَّلْ حَتَّى إِذَا بَلَغَتْ الْحُلْقُومَ قُلْتَ لِفُلَانٍ كَذَا وَلِفُلَانٍ كَذَا وَقَدْ كَانَ لِفُلَانٍ ‏","","",""],[9010,9010,"","ঈশ্বর নিজেকে মুসলমান করে নিয়েছেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كَانَتْ شَجَرَةٌ تُؤْذِي أَهْلَ الطَّرِيقِ فَقَطَعَهَا رَجُلٌ فَنَحَّاهَا فَدَخَلَ الْجَنَّةَ ‏","","",""],[9011,9011,"","আমরা আমার ভালবাসার বিষয়ে বাবার বাপ্তিস্মের কথা বলেছিলাম, আমার ভালবাসা দেবীর কাছে, তিনি বলেছিলেন যে, প্রাচীনের পুত্র পুত্রই হচ্ছে প্রাচীনের পুত্র কুর্দি, খোদা দোয়া করেন তারা একত্র হয়েছেন","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الْكَرِيمَ ابْنَ الْكَرِيمِ ابْنِ الْكَرِيمِ ابْنِ الْكَرِيمِ ‏ ‏يُوسُفُ بْنُ يَعْقُوبَ بْنِ إِسْحَقَ بْنِ إِبْرَاهِيمَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِمْ أَجْمَعِينَ ‏","","",""],[9012,9012,"","বাবা যে - কথা না শোনে, আমরা তার কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ فَرَاهِيجَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏مَا كَانَ لَنَا عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏طَعَامٌ إِلَّا الْأَسْوَدَانِ التَّمْرُ وَالْمَاءُ ‏","","",""],[9013,9013,"","আমরা আমার বাবার সাথে একটা মসজিদে গিয়ে ধরা পড়ি, যে হয়ত বলতে পারে যে ক্ষতি হয়েছে। সে আত্মসমর্পণ করেছে","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏إِبْرَاهِيمُ بْنُ الْمُهَاجِرِ ‏ ‏أَخْبَرَنِي قَالَ سَمِعْتُ ‏ ‏أَبَا الشَّعْثَاءِ الْمُحَارِبِيَّ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏فِي مَسْجِدٍ ‏ ‏فَخَرَجَ رَجُلٌ وَقَدْ أَذَّنَ الْمُؤَذِّنُ قَالَ فَقَالَ أَمَّا هَذَا فَقَدْ عَصَى ‏ ‏أَبَا الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[9014,9014,"","আমার বাবার সবচেয়ে ভাল বাড়লে আমি আমার ছেলের বাপ্তিস্মের কথা বলেছিলাম। যে ব্যক্তি রেগে যায় এবং এরপর বলে যে, যদি একজন পুরুষ বা পুরুষের স্ত্রী থাকে অথবা তার পিতা থাকে, তাহলে তার বাবা রয়েছে যার বাবা বা বাবা থাকে তার বাবা থাকে তার বাবা। পিতা-মাতা যদি তার পিতা পিতা পিতা , যে তার পিতা পিতা পিতা , তার বাবা হন, যে তার পিতা পিতা রয়েছে, যদি তার পিতা পিতা হয় তবে তার বাবা হয় তার মা, যে তার বাবাও (পিতার) আমার বাবা আছেন, যার বাবা আছে। তারা এই প্রার্থনাকে ভয় পায় যে তারা এমন একজন মানুষকে আদেশ দিয়েছে যে হয়তো এই অকুতির কষ্ট সহ্য করতে ব্যর্থ হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ بَهْدَلَةَ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخَّرَ الْعِشَاءَ الْآخِرَةَ ذَاتَ لَيْلَةٍ حَتَّى كَادَ يَذْهَبُ ثُلُثُ اللَّيْلِ ‏ ‏أَوْ قُرَابُهُ ‏ ‏قَالَ ثُمَّ جَاءَ وَفِي النَّاسِ ‏ ‏رِقَّةٌ ‏ ‏وَهُمْ ‏ ‏عِزُونَ ‏ ‏فَغَضِبَ غَضَبًا شَدِيدًا ثُمَّ قَالَ ‏ ‏لَوْ أَنَّ رَجُلًا ‏ ‏بَدَا ‏ ‏النَّاسَ إِلَى ‏ ‏عَرْقٍ ‏ ‏أَوْ ‏ ‏مِرْمَاتَيْنِ ‏ ‏لَأَجَابُوا لَهُ وَهُمْ يَتَخَلَّفُونَ عَنْ هَذِهِ الصَّلَاةِ لَقَدْ هَمَمْتُ أَنْ آمُرَ رَجُلًا فَيَتَخَلَّفَ عَلَى أَهْلِ هَذِهِ الدُّورِ الَّذِينَ يَتَخَلَّفُونَ عَنْ هَذِهِ الصَّلَاةِ فَأُحَرِّقَهَا عَلَيْهِمْ بِالنِّيرَانِ ‏","","",""],[9015,9015,"","আমাদের বাবা একজন উৎপীড়ক ছিলেন, যিনি তাকে বলেছিলেন যে, তিনি একজন যাজক নন ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو المُهَزِّمِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ ‏ ‏فَاطِمَةَ ‏ ‏أَوْ ‏ ‏أُمَّ سَلَمَةَ ‏ ‏أَنْ تَجُرَّ ذَيْلَهَا ذِرَاعًا ‏","","",""],[9016,9016,"","আমি আমার বাবার ব্যাপারে অনেক কথা বলেছি, আমি তার নিজের কথা শুনেছি, ঈশ্বরের কথা শুনে আমি একজন পরাজিত এবং সে আমাকে বলছে এটা সত্য. আমার ছড়ি ঈশ্বর এবং তার উপর ছেড়ে চলে গেছে. যারা রাজকুমারের বাধ্য হয়েছে তারা আমাকে ছেড়ে চলে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي عَلْقَمَةَ الْأَنْصَارِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏مِنْ ‏ ‏فِيهِ إِلَى ‏ ‏فِيَّ قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ أَطَاعَنِي فَقَدْ أَطَاعَ اللَّهَ وَمَنْ عَصَانِي فَقَدْ عَصَى اللَّهَ وَمَنْ أَطَاعَ الْأَمِيرَ فَقَدْ أَطَاعَنِي إِنَّمَا الْأَمِيرُ ‏ ‏مِجَنٌّ ‏ ‏فَإِنْ صَلَّى جَالِسًا فَصَلُّوا جُلُوسًا أَوْ قُعُودًا فَإِذَا قَالَ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ فَقُولُوا اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ فَإِنَّهُ إِذَا وَافَقَ قَوْلُ أَهْلِ الْأَرْضِ قَوْلَ أَهْلِ السَّمَاءِ غُفِرَ لَهُ مَا مَضَى مِنْ ذَنْبِهِ ‏","","",""],[9017,9017,"","সে বলেছিল সে তার প্রতিশ্রুতির সংক্ষিপ্ত অংশ হবে এবং সে তার হৃদয় ভেঙ্গে ফেলবে।","‏ ‏قَالَ ‏ ‏وَيَهْلِكُ ‏ ‏قَيْصَرُ ‏ ‏فَلَا يَكُونُ ‏ ‏قَيْصَرُ ‏ ‏بَعْدَهُ وَيَهْلِكُ ‏ ‏كِسْرَى ‏ ‏فَلَا يَكُونُ ‏ ‏كِسْرَى ‏ ‏بَعْدَهُ ‏","","",""],[9018,9018,"","তিনি বলেছিলেন, ঈশ্বর যাতে অপমানিত হন এবং মৃত্যুর জন্য তিনি পাঁচটি পাপ ও ব্যবহার করেন ।","‏ ‏وَقَالَ ‏ ‏اسْتَعِيذُوا بِاللَّهِ مِنْ خَمْسٍ مِنْ عَذَابِ جَهَنَّمَ وَعَذَابِ الْقَبْرِ ‏ ‏وَفِتْنَةِ ‏ ‏الْمَحْيَا وَالْمَمَاتِ ‏ ‏وَفِتْنَةِ ‏ ‏الْمَسِيحِ الدَّجَّالِ ‏","","",""],[9019,9019,"","আমি আমার বাবাকে যাজক হওয়ার কথা বলেছিলাম। ঈশ্বর যদি আমার জীবনের ১০% পর্যন্ত বিশ্বাস করে... ...আমি প্রভু আমার সমস্ত ইচ্ছার উপর বিশ্বাস স্থাপন করুন, তারা আটকে আছে। মাইডার্সের দেয়াল।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو هِلَالٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ آمَنَ بِي عَشَرَةٌ مِنْ ‏ ‏أَحْبَارِ ‏ ‏الْيَهُودِ ‏ ‏لَآمَنَ بِي كُلُّ يَهُودِيٍّ عَلَى وَجْهِ الْأَرْضِ ‏ ‏قَالَ ‏ ‏كَعْبٌ ‏ ‏اثْنَا عَشَرَ مِصْدَاقُهُمْ فِي سُورَةِ ‏ ‏الْمَائِدَةِ ‏","","",""],[9020,9020,"","আমি আমার বাবাকে আমার ভালোবাসা বলার জন্য একটা ভালো লর্ডকে দিতে বলেছিলাম। সব প্রার্থনায়, ঈশ্বরের নামে আমরা ঈশ্বরের নামে শুনেছি, তার কাছে একটা মই আছে, আমি তোমার কথা শুনতে চাই, আর আমি ভয় পাই যে তুমি ভয় পাও। যে লোক এই জন ্ য বেঁচে থাকবে সে-ই হবে সাহায ্ য করবে , আর যে হবে সে হবে ক ্ ষতিগ ্ রস ্ ত । আর সেই হবে সেই ব্যক্তি যিনি তোমাকে সবচেয়ে বেশি ভয় পাবেন।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏قَيْسٌ ‏ ‏وحَبِيبٌ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ أَبِي رَبَاحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ قَالَ ‏ ‏فِي كُلِّ الصَّلَوَاتِ يُقْرَأُ فَمَا أَسْمَعَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْمَعْنَاكُمْ وَمَا أَخْفَى عَنَّا أَخْفَيْنَا عَنْكُمْ ‏","","",""],[9021,9021,"","আমরা কথা বলেছি, ঈশ্বর কিভাবে আমাকে বলেছিলেন আমি ঈশ্বরের কথা শুনেছি আমি আমার বাবা একজন মানুষ, যে ঈশ্বরের দোহাইর জন্য প্রার্থনা করবে এবং তার প্রভুর সেবা করবে। তিনি বললেন, তিনি যেতে দিয়েছেন। সে বলেছে তার কাছে দ্বিতীয়টা আছে, তারা তাকে দেবে, আমি তোমাকে সুস্থ করে ফেলব।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَنْبَأَنِي ‏ ‏سَلَمَةُ بْنُ كُهَيْلٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَلَمَةَ بْنَ عَبْدِ الرَّحْمَنِ ‏ ‏بِمِنًى ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَجُلًا أَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَقَاضَاهُ فَأَغْلَظَ لَهُ قَالَ فَهَمَّ بِهِ أَصْحَابُهُ فَقَالَ دَعُوهُ ‏ ‏فَإِنَّ لِصَاحِبِ الْحَقِّ مَقَالًا قَالَ اشْتَرُوا لَهُ بَعِيرًا فَأَعْطُوهُ إِيَّاهُ قَالُوا لَا نَجِدُ إِلَّا ‏ ‏سِنًّا ‏ ‏أَفْضَلَ مِنْ ‏ ‏سِنِّهِ ‏ ‏قَالَ فَاشْتَرُوهُ فَأَعْطُوهُ إِيَّاهُ فَإِنَّ مِنْ خَيْرِكُمْ أَحْسَنَكُمْ ‏ ‏قَضَاءً ‏","","",""],[9022,9022,"","আমরা আমার বাবার কথা বলেছিলাম, সে বাপ্তিস্মের কথা বলেছে যে কারা জেলে যাবে, সে এটা করতে পারবে না। সে কখনো দেখেনি, যদি সে শুনতে না থাকতো এবং কখনো তার কোন খবর ছিল না। হার্টবিট।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيمَا يَحْسَبُ ‏ ‏حَمَّادٌ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ يَدْخُلُ الْجَنَّةَ يَنْعَمُ لَا يَبْأَسُ لَا ‏ ‏تَبْلَى ‏ ‏ثِيَابُهُ وَلَا ‏ ‏يَفْنَى شَبَابُهُ فِي الْجَنَّةِ مَا لَا عَيْنٌ رَأَتْ وَلَا أُذُنٌ سَمِعَتْ وَلَا خَطَرَ عَلَى قَلْبِ بَشَرٍ ‏","","",""],[9023,9023,"","আমরা এক সুখী কথা লিখতে পেরে আনন্দিত হয়েছিলাম, যার কারণে আমরা এক বিশেষ ছেলের অনুগ্রহ লাভ করেছি । আমার ক্ষমতা আছে, আমার বাবাকে দেখে খুশি হলাম, একজন জিনিয়াস যে ঈশ্বরের কাছে নিজের কথা বলতে পারবে আর আমার প্রভুর কাছে পৌঁছে দেবে। আমরা সিদ্ধান্ত নিয়েছি যে আমি সেই দলেরই অংশ। আমি যদি এখন আর কখনো ভুলবো না। আগে আমি ছিলাম।","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ مُحَمَّدِ بْنِ عَبْدٍ الْقَارِيُّ ‏ ‏مِنْ قَبِيلَةٍ يُقَالُ لَهَا ‏ ‏قَارَةُ ‏ ‏مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏وَنَزَلَ ‏ ‏الْإِسْكَنْدَرِيَّةَ ‏ ‏بَلَدُ بَابِ ‏ ‏مِصْرَ ‏ ‏فَقِيلَ لَهُ ‏ ‏الْإِسْكَنْدَرَانِيُّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَبِي عَمْرٍو ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بُعِثْتُ فِي خَيْرِ قُرُونِ بَنِي ‏ ‏آدَمَ ‏ ‏قَرْنًا فَقَرْنًا حَتَّى كُنْتُ مِنْ الْقَرْنِ الَّذِي كُنْتُ فِيهِ ‏","","",""],[9024,9024,"","ঈশ্বরের অনুগ্রহে আমরা আমাদের প্রাণ দিয়ে আমাদের হত্যা করার চেষ্টা করেছি, যাতে ভালো কিছু করার জন্য আমি ঈশ্বরের কাছে প্রার্থনা করি এবং বলি ঈশ্বর খুশি এবং আমি অবশ্যই আমার সেরাটা খেলব। পাগল হয়ে যাবে না।","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَبِي عَمْرٍو ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَقُولُ اللَّهُ عَزَّ وَجَلَّ ‏ ‏مَا لِعَبْدِي الْمُؤْمِنِ عِنْدِي جَزَاءٌ إِذَا ‏ ‏قَبَضْتُ ‏ ‏صَفِيَّهُ ‏ ‏مِنْ أَهْلِ الدُّنْيَا ثُمَّ ‏ ‏احْتَسَبَهُ ‏ ‏إِلَّا الْجَنَّةُ ‏","","",""],[9025,9025,"","আমরা চেষ্টা করেছি আর বলতে চাই যে বাবার ভালোবাসা ফিরিয়ে আনার সিদ্ধান্তের জন্য আমাদের সময় শাস্তি হচ্ছে। বল, কে এটা বছর পার করেছে।","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ عَمَّرَهُ اللَّهُ سِتِّينَ سَنَةً فَقَدْ أَعْذَرَ اللَّهُ إِلَيْهِ فِي الْعُمُرِ ‏","","",""],[9026,9026,"","আমরা একটি সুখী ছেলেকে খুন করার চেষ্টা করেছি যে বলেছে আমরা তার বাবার অনুগ্রহের জন্য শাস্তি পেয়েছি. আমি বাইরে গিয়ে বাইরে গিয়ে বাইরে গিয়ে বাইরে গিয়ে বাইরে যাই!","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى يَكْثُرَ الْمَالُ ‏ ‏وَيَفِيضَ ‏ ‏حَتَّى يَخْرُجَ الرَّجُلُ بِزَكَاةِ مَالِهِ فَلَا يَجِدُ أَحَدًا يَقْبَلُهَا مِنْهُ وَحَتَّى تَعُودَ أَرْضُ ‏ ‏الْعَرَبِ ‏ ‏مُرُوجًا ‏ ‏وَأَنْهَارًا وَحَتَّى يَكْثُرَ ‏ ‏الْهَرْجُ ‏ ‏قَالُوا وَمَا ‏ ‏الْهَرْجُ ‏ ‏يَا رَسُولَ اللَّهِ قَالَ الْقَتْلُ الْقَتْلُ ‏","","",""],[9027,9027,"","আমি ঈশ্বরের কসম কেটে বলছি, সে তার কাছে প্রার্থনা করেছে আর সে আত্মসমর্পণ করবে যে কিনা সমুদ্রহীন.","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ حَمَلَ عَلَيْنَا السِّلَاحَ فَلَيْسَ مِنَّا وَمَنْ غَشَّنَا فَلَيْسَ مِنَّا ‏","","",""],[9028,9028,"","তিনি বলেন যে, কে একজন রোগীকে কেনার তিন দিনের মধ্যেই তাকে স্পর্শ করে চলে যায় ।","‏ ‏وَقَالَ ‏ ‏مَنْ ‏ ‏ابْتَاعَ ‏ ‏شَاةً ‏ ‏مُصَرَّاةً ‏ ‏فَهُوَ فِيهَا ‏ ‏بِالْخِيَارِ ‏ ‏ثَلَاثَةَ أَيَّامٍ فَإِنْ شَاءَ أَمْسَكَهَا وَإِنْ شَاءَ رَدَّهَا وَرَدَّ مَعَهَا ‏ ‏صَاعًا ‏ ‏مِنْ تَمْرٍ ‏","","",""],[9029,9029,"","সে বলেছিল তুমি লর্ডের সাথে লড়াই করবে না... ...আমি লর্ডের সাথে লড়াই করতে চাই... ...আমি চাই... ...যে আমি প্রভুর সাথে বিশ্বাসঘাতকতা করুক, গাছটা বলে দেবে, কিন্তু ঈশ্বর এটাকে শাসন করে নিবাও।","‏ ‏وَقَالَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى يُقَاتِلَ الْمُسْلِمُونَ ‏ ‏الْيَهُودَ ‏ ‏فَيَقْتُلَهُمْ الْمُسْلِمُونَ حَتَّى يَخْتَبِئَ الْيَهُودِيُّ وَرَاءَ الْحَجَرِ أَوْ الشَّجَرَةِ فَيَقُولُ الْحَجَرُ أَوْ الشَّجَرُ يَا مُسْلِمُ يَا عَبْدَ اللَّهِ هَذَا يَهُودِيٌّ خَلْفِي فَتَعَالَ فَاقْتُلْهُ إِلَّا ‏ ‏الْغَرْقَدَ ‏ ‏فَإِنَّهُ مِنْ شَجَرِ ‏ ‏الْيَهُودِ ‏","","",""],[9030,9030,"","তিনি আমার মায়ের সবচেয়ে ভাল প্রেম যারা আমার পরে তাদের দেখতে চায়।","‏ ‏وَقَالَ ‏ ‏مِنْ أَشَدِّ أُمَّتِي لِي حُبًّا نَاسٌ يَكُونُونَ بَعْدِي يَوَدُّ أَحَدُهُمْ لَوْ رَآنِي بِأَهْلِهِ وَمَالِهِ ‏","","",""],[9031,9031,"","সে বলেছে, সে সালামকে নিয়ে যেতে এবং সেটা করতে করতে পেরে খুব ভালো ছিল।","‏ ‏وَقَالَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏مَنْ ‏ ‏تَوَلَّى ‏ ‏قَوْمًا بِغَيْرِ إِذْنِ ‏ ‏مَوَالِيهِ ‏ ‏فَعَلَيْهِ لَعْنَةُ اللَّهِ وَالْمَلَائِكَةِ لَا يَقْبَلُ اللَّهُ مِنْهُ ‏ ‏صَرْفًا ‏ ‏وَلَا ‏ ‏عَدْلًا ‏","","",""],[9032,9032,"","সে বলল যে ঈশ্বর এটা উদ্ধার করতে হবে এবং তার গলার কথা শুনবে এবং বলবে কে ব্যর্থ হয়েছে। সে বলল আমি তাদের বিষ খেতে পারি, হয়তো তার জন্য আমাদের একটা টোপ ছিল।","‏ ‏وَقَالَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَالَ الْقَارِئُ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ فَقَالَ مَنْ خَلْفَهُ اللَّهُمَّ رَبَّنَا وَلَكَ الْحَمْدُ فَوَافَقَ قَوْلُهُ ذَلِكَ قَوْلَ أَهْلِ السَّمَاءِ اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏","","",""],[9033,9033,"","আমরা আমাদের নিজেদের বাবাকে হত্যা করার চেষ্টা করেছিলাম, তার বাবার জন্য তাকে মেরে ফেলার জন্য আমাকে বলেছিলাম যে, সে খুবই বৃদ্ধ ।","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يُكَبِّرُ كُلَّمَا خَفَضَ وَرَفَعَ وَيُحَدِّثُ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَفْعَلُ ذَلِكَ ‏","","",""],[9034,9034,"","আমরা আমাদের বাবাকে কুমারী হিসেবে শাস্তি দেওয়ার চেষ্টা করেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ قَالَ ‏ ‏شَكَا النَّاسُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتْحَ مَا بَيْنَ الْمِرْفَقَيْنِ ‏ ‏فَأَمَرَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَسْتَعِينُوا بِالرُّكَبِ ‏","","",""],[9035,9035,"","আমরা একটি সুখী দম্পতি লিখতে চেষ্টা করেছি আমার বাবা এবং ঈশ্বরের তৃতীয় অন্ত্যেষ্টিক্রিয়ার আগে। আমার বাবা একজন পলাতক। তিনি ঈশ্বরের কাছে প্রার্থনা করেছিলেন যে তিনি তার কাছে প্রার্থনা করবেন। আত্মসমর্পণ করো.","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي ثِفَالٍ الْمُرِّيِّ ‏ ‏عَنْ ‏ ‏رَبَاحِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَمُ ‏ ‏عَفْرَاءَ ‏ ‏أَحَبُّ إِلَيَّ مِنْ دَمِ سَوْدَاوَيْنِ ‏","","",""],[9036,9036,"","আমরা একটি সুখী ছেলেকে লিখতে চেষ্টা করেছি, আমরা আমার বাবার জন্য তৃতীয়বারের মতো একটি কুষ্ঠি সন্তান খুঁজে পেয়েছি। ঈশ্বর আদেশ দিয়েছেন, যেন তিনি তাকে একই ইচ্ছা এবং ভালবাসার ইচ্ছার সমর্পণ করেন। প্রতারণা।","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏ثَوْرِ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الْغَيْثِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏ذُو السُّوَيْقَتَيْنِ ‏ ‏مِنْ ‏ ‏الْحَبَشَةِ ‏ ‏يُخَرِّبُ ‏ ‏بَيْتَ اللَّهِ ‏ ‏عَزَّ وَجَلَّ ‏","","",""],[9037,9037,"","ঈশ্বর বলেছিলেন যে, ঈশ্বর তা উদ্ধার করতে হবে এবং এমনকি এমন কোনো ব্যক্তিকেও যেন সেই দেশ থেকে বের করে না নিয়ে যেতে পারেন, যে কিনা তাঁর তীর দিয়ে লোকেদের ধ্বংস করে দেবে ।","‏ ‏وَقَالَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى يَخْرُجَ رَجُلٌ مِنْ ‏ ‏قَحْطَانَ ‏ ‏يَسُوقُ النَّاسَ بِعَصَاهُ ‏","","",""],[9038,9038,"","আমরা আমার বাবাকে কয়েক বছর ধরে কুমারী হিসেবে খুঁজে বের করার চেষ্টা করেছি। লর্ড তার পতাকা আদেশ দিয়েছেন এবং তাঁর প্রতি তার করুণা প্রদর্শন করবেন। আল্লাহ যেন তাকে শান্তি নিয়ে আসেন না, আল্লাহ তার প্রতি দয়া দেখান। কিন্তু, সেই ভাববাদীর কাছে প্রার্থনা করার সময় তার হাত দুটো কেটে ফেলতে হতো । যদি সে তৃতীয় হয় তাহলে ঐ বমির লোকগুলো","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏ثَوْرٍ ‏ ‏عَنْ ‏ ‏أَبِي الْغَيْثِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّهُ قَالَ ‏ ‏كُنَّا جُلُوسًا عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذْ نَزَلَتْ عَلَيْهِ سُورَةُ ‏ ‏الْجُمُعَةِ ‏ ‏فَلَمَّا قَرَأَ ‏ { ‏وَآخَرِينَ مِنْهُمْ لَمَّا يَلْحَقُوا بِهِمْ ‏} ‏قَالَ مَنْ هَؤُلَاءِ يَا رَسُولَ اللَّهِ فَلَمْ يُرَاجِعْهُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى سَأَلَهُ مَرَّةً ‏ ‏أَوْ مَرَّتَيْنِ أَوْ ثَلَاثًا ‏ ‏وَفِينَا ‏ ‏سَلْمَانُ الْفَارِسِيُّ ‏ ‏قَالَ فَوَضَعَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدَهُ عَلَى ‏ ‏سَلْمَانَ ‏ ‏وَقَالَ ‏ ‏لَوْ كَانَ الْإِيمَانُ عِنْدَ ‏ ‏الثُّرَيَّا ‏ ‏لَنَالَهُ رِجَالٌ مِنْ هَؤُلَاءِ ‏","","",""],[9039,9039,"","আমরা আমার বাবার কথা বলেছিলাম আমার বাবার সাথে একজন উৎপীড়ক হওয়ার কথা, তাকে বলতে হবে কে মানুষের টাকা নিয়েছে তার জন্য আর কার জন্য সে নিজেকে নিয়ে নিয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏ثَوْرٍ ‏ ‏عَنْ ‏ ‏أَبِي الْغَيْثِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَخَذَ أَمْوَالَ النَّاسِ يُرِيدُ أَدَاءَهَا أَدَّى اللَّهُ عَنْهُ وَمَنْ أَخَذَهَا يُرِيدُ ‏ ‏يَعْنِي تَلَفَهَا أَتْلَفَهُ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[9040,9040,"","আমরা নিজেদেরকে মারতে চেষ্টা করেছি, কিন্তু আমার বাবার চেয়ে ভালো। সে তার জন্য প্রার্থনা করেছিল এবং সে ছিল দুই বছরের ছেলে।","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْمُغِيرَةُ بْنُ عَبْدِ الرَّحْمَنِ الْقُرَشِيُّ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اخْتَتَنَ ‏ ‏إِبْرَاهِيمُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏وَهُوَ ابْنُ ثَمَانِينَ سَنَةً ‏ ‏بِالْقَدُومِ ‏","","",""],[9041,9041,"","সে বলল, সে তার চোখের সামনে সূর্য তুলে, আর মুখ বন্ধ করে দিয়েছে। বন্ধুদের মধ্যে নয়।","‏ ‏وَقَالَ ‏ ‏خَيْرُ يَوْمٍ طَلَعَتْ عَلَيْهِ الشَّمْسُ يَوْمُ الْجُمُعَةِ فِيهِ خُلِقَ ‏ ‏آدَمُ ‏ ‏وَفِيهِ أُدْخِلَ الْجَنَّةَ وَفِيهِ أُخْرِجَ مِنْهَا وَلَا تَقُومُ السَّاعَةُ إِلَّا فِي يَوْمِ الْجُمُعَةِ ‏","","",""],[9042,9042,"","সে বলল, ঈশ্বর জিতে গেছে আর তার সাথে দেখা করতে আমার অনেক ভালো লাগে।","‏ ‏قَالَ وَقَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏إِذَا أَحَبَّ عَبْدِي لِقَائِي أَحْبَبْتُ لِقَاءَهُ وَإِذَا كَرِهَ لِقَائِي كَرِهْتُ لِقَاءَهُ ‏","","",""],[9043,9043,"","তিনি বলেছিলেন যে, তার প্রার্থনা ও সালাদের দরকার ছিল, যেন তারা সেই সম্মানকে কাজে লাগায়, যা ভাইকে ও ভাইয়ের কর্মদক্ষতা নিয়ন্ত্রণ করতে সাহায্য করে ।","‏ ‏وَقَالَ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏رَأْسُ الْكُفْرِ نَحْوَ الْمَشْرِقِ وَالْفَخْرُ ‏ ‏وَالْخُيَلَاءُ ‏ ‏فِي أَهْلِ الْخَيْلِ وَالْإِبِلِ ‏ ‏وَالْفَدَّادِينَ ‏ ‏أَهْلِ ‏ ‏الْوَبَرِ ‏ ‏وَالسَّكِينَةُ ‏ ‏فِي أَهْلِ الْغَنَمِ ‏","","",""],[9044,9044,"","সে বলেছে, তুমি জানো সে না আসা পর্যন্ত আমি কার জন্য ঘৃণা করি।","‏ ‏وَقَالَ ‏ ‏تَجِدُونَ مِنْ خَيْرِ النَّاسِ أَشَدَّهُمْ كَرَاهِيَةً لِهَذَا الشَّأْنِ حَتَّى يَقَعَ فِيهِ ‏","","",""],[9045,9045,"","যদি তিনি শেষ কোয়ার্টার থেকে তার মন বড় করে দিতেন... ...তারা আমার বাবার জীবন রক্ষা করতে পেরেছে, ঈশ্বর ঈশ্বরের প্রভু, প্রভু ঈশ্বরের প্রভু, যার কথা তোমাকে বিশ্বাস করার কথা ছিল. এটা দুই বছর পর আমার জিহ্বা সিঁড়ির উপরে চলে যাবে.","‏ ‏وَكَانَ إِذَا رَفَعَ رَأْسَهُ مِنْ الرَّكْعَةِ الْآخِرَةِ يَقُولُ ‏ ‏اللَّهُمَّ أَنْجِ ‏ ‏عَيَّاشَ بْنَ أَبِي رَبِيعَةَ ‏ ‏اللَّهُمَّ أَنْجِ ‏ ‏سَلَمَةَ بْنَ هِشَامٍ ‏ ‏اللَّهُمَّ أَنْجِ ‏ ‏الْوَلِيدَ بْنَ الْوَلِيدِ ‏ ‏اللَّهُمَّ أَنْجِ الْمُسْتَضْعَفِينَ مِنْ الْمُؤْمِنِينَ اللَّهُمَّ اشْدُدْ ‏ ‏وَطْأَتَكَ ‏ ‏عَلَى ‏ ‏مُضَرَ ‏ ‏اللَّهُمَّ اجْعَلْهَا سِنِينَ ‏ ‏كَسِنِي ‏ ‏يُوسُفَ ‏ ‏عَلَيْهِ السَّلَام ‏","","",""],[9046,9046,"","সে বলল খোদা তাকে মাফ করে দেবে আর আমি এটা করবো।","‏ ‏وَقَالَ ‏ ‏غِفَارٌ ‏ ‏غَفَرَ اللَّهُ لَهَا ‏ ‏وَأَسْلَمُ ‏ ‏سَالَمَهَا اللَّهُ ‏","","",""],[9047,9047,"","সে বলেছিল যে, যে কিনা তার হাতে বাপ্তিস্ম নিচ্ছে... ...যদি তুমি জানো আমি তোমার বাবার ব্যাপারে জানি না।","‏ ‏وَقَالَ وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ ‏ ‏لَوْ تَعْلَمُونَ مَا أَعْلَمُ لَبَكَيْتُمْ كَثِيرًا وَلَضَحِكْتُمْ قَلِيلًا ‏","","",""],[9048,9048,"","তিনি যা বলেছেন তাই বলেছেন আর প্রার্থনা করুন, তিনি বলেছেন, আমি তোমার মতো নই, আর তিনি আমাকে তার মত করে রেখেছেন।","‏ ‏وَقَالَ ‏ ‏إِيَّاكُمْ ‏ ‏وَالْوِصَالَ ‏ ‏قَالُوا فَإِنَّكَ ‏ ‏تُوَاصِلُ ‏ ‏يَا رَسُولَ اللَّهِ قَالَ إِنِّي لَسْتُ فِي ذَا مِثْلَكُمْ إِنِّي أَبِيتُ يُطْعِمُنِي رَبِّي وَيَسْقِينِي فَاكْلَفُوا مَا لَكُمْ بِهِ طَاقَةٌ ‏","","",""],[9049,9049,"","সে বলেছে যে খোদা শহরের একটা গাছের মধ্যে উদ্ধার করতে পারবে... ...যে কিনা একজন যাত্রীকে তার ছায়াতে নিয়ে যাবে একশ বছর।","‏ ‏وَقَالَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْجَنَّةِ شَجَرَةٌ يَسِيرُ الرَّاكِبُ فِي ظِلِّهَا مِائَةَ سَنَةٍ لَا يَقْطَعُهَا ‏","","",""],[9050,9050,"","আমরা একটি সুখী দম্পতি লিখতে চেষ্টা করেছি, আমি একটি mooolll এর জন্য আমি লজ্জিত মানে তিনি বলেন তিনি তাকে আদেশ করেছেন এবং তিনি আপনার জন্য শান্তি পাবেন না।","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُوسَى يَعْنِي الْمَخْزُومِيَّ ‏ ‏عَنْ ‏ ‏يَعْقُوبَ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا صَلَاةَ لِمَنْ لَا وُضُوءَ لَهُ وَلَا وُضُوءَ لِمَنْ لَمْ يَذْكُرْ اسْمَ اللَّهِ عَلَيْهِ ‏","","",""],[9051,9051,"","আমরা আমাদের হত্যা করার চেষ্টা করেছি, ঈশ্বর তাকে আমার কাছে প্রার্থনা করেছেন এবং তাকে আমার কাছে আত্মসমর্পণ করেছেন যে তাকে খুঁজে পেয়েছে। তার মজার দিকে তাকিয়ে আছে।","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَاتِمُ بْنُ إِسْمَاعِيلَ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ الْخَرَّاطِ ‏ ‏عَنِ ‏ ‏الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ جَاءَ ‏ ‏مَسْجِدِي ‏ ‏هَذَا لَمْ يَأْتِ إِلَّا لِخَيْرٍ يَتَعَلَّمُهُ فَهُوَ بِمَنْزِلَةِ الْمُجَاهِدِ فِي سَبِيلِ اللَّهِ وَمَنْ جَاءَ لِغَيْرِ ذَلِكَ فَهُوَ بِمَنْزِلَةِ رَجُلٍ يَنْظُرُ إِلَى مَتَاعِ غَيْرِهِ ‏","","",""],[9052,9052,"","আমরা চেষ্টা করেছি এবং এমন একটা আংটি খুঁজে বের করার চেষ্টা করেছি যা আমাকে ঈশ্বরের প্রেমে জিততে সাহায্য করবে। সে আশা করে যেন এটা তার কাছে ঘটেছে এবং তার আত্মাকে তার কাছে সমর্পণ করে... - একটু ধরো।","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏حَاتِمُ بْنُ إِسْمَاعِيلَ ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ مُحَمَّدِ بْنِ زَائِدَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏مَا رَفَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأْسَهُ إِلَى السَّمَاءِ إِلَّا قَالَ ‏ ‏يَا مُصَرِّفَ الْقُلُوبِ ثَبِّتْ قَلْبِي عَلَى طَاعَتِكَ ‏","","",""],[9053,9053,"","আমরা চেষ্টা করেছি এবং বলতে চাই যে আমাদের একটি নির্দিষ্ট ছেলের সাথে জয় করতে হবে। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং কখনো তার আত্মাকে ক্ষমা করবেন না। একজন মানুষ ভুল করার জন্য তার দড়ি নিয়ে যায়।","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ يَعْنِي ابْنَ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَفْتَحُ الْإِنْسَانُ عَلَى نَفْسِهِ بَابَ مَسْأَلَةٍ إِلَّا فَتَحَ اللَّهُ عَلَيْهِ بَابَ فَقْرٍ يَأْخُذُ الرَّجُلُ حَبْلَهُ فَيَعْمِدُ إِلَى الْجَبَلِ فَيَحْتَطِبُ عَلَى ظَهْرِهِ فَيَأْكُلُ بِهِ خَيْرٌ لَهُ مِنْ أَنْ يَسْأَلَ النَّاسَ مُعْطًى أَوْ مَمْنُوعًا ‏","","",""],[9054,9054,"","আমরা চেষ্টা করেছি বাবার স্বপ্নের চেয়ে নিজেকে আরও ভালো করার জন্য, আল্লাহ তার জন্য প্রার্থনা করেছেন এবং সাত বছরের সকল শিশুর জন্য নিজেকে উৎসর্গ করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَرَّمَ كُلَّ ذِي ‏ ‏نَابٍ مِنْ السِّبَاعِ ‏","","",""],[9055,9055,"","আমরা চেষ্টা করেছি একটি ছেলে, যে কিনা মুখ বন্ধ রাখতে পারে এমন একটি ছেলেকে সাহায্য করার জন্য যে ছেলে, তাকে আমি প্রার্থনা করব ঈশ্বরের কাছে প্রার্থনা করব এবং সে বিশ্বাস ছাড়া বলবে না। লর্ডের হাতে কিংবা ঈশ্বরের ঈশ্বরের উপর ভরসা রেখে এটা সঠিকভাবে চলতে পারবে না।","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ مُضَرَ ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏أَنَّ ‏ ‏سَعِيدَ بْنَ يَسَارٍ أَبَا الْحُبَابِ ‏ ‏أخْبَرَهُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ عَبْدٍ مُؤْمِنٍ تَصَدَّقَ ‏ ‏بِصَدَقَةٍ ‏ ‏مِنْ طَيِّبٍ وَلَا يَقْبَلُ اللَّهُ إِلَّا طَيِّبًا وَلَا يَصْعَدُ السَّمَاءَ إِلَّا طَيِّبٌ إِلَّا وَهُوَ يَضَعُهَا فِي يَدِ الرَّحْمَنِ ‏ ‏أَوْ فِي كَفِّ الرَّحْمَنِ ‏ ‏فَيُرَبِّيهَا لَهُ كَمَا يُرَبِّي أَحَدُكُمْ ‏ ‏فَلُوَّهُ ‏ ‏أَوْ ‏ ‏فَصِيلَهُ ‏ ‏حَتَّى إِنَّ التَّمْرَةَ لَتَكُونُ مِثْلَ الْجَبَلِ الْعَظِيمِ ‏","","",""],[9056,9056,"","আমরা নিজেকে মারতে চেষ্টা করেছি, আমার ছেলে বাবার ছেলের সম্পর্কে একটা ধারণা থাকার প্রবণতা আছে, সে বলবে তারা ভালো না, না হলে তারা একত্রিত হবে। আমি বলতে চাচ্ছি, তারা হচ্ছে...","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏دَرَّاجٍ ‏ ‏عَنِ ‏ ‏ابْنِ حُجَيْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ لِلْمَسَاجِدِ أَوْتَادًا الْمَلَائِكَةُ جُلَسَاؤُهُمْ إِنْ غَابُوا يَفْتَقِدُونَهُمْ وَإِنْ مَرِضُوا عَادُوهُمْ وَإِنْ كَانُوا فِي حَاجَةٍ أَعَانُوهُمْ ‏","","",""],[9057,9057,"","তিনি ঈশ্বরকে বলেছিলেন যে, তাঁকে গৌরবের আইন তিন বার বিশেষ ভাই বা ক্লাসের সামনে পেশ করতে হবে।","‏ ‏وَقَالَ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَلِيسُ الْمَسْجِدِ عَلَى ثَلَاثِ خِصَالٍ أَخٍ مُسْتَفَادٍ أَوْ كَلِمَةٍ مُحْكَمَةٍ أَوْ رَحْمَةٍ مُنْتَظَرَةٍ ‏","","",""],[9058,9058,"","আমরা চেষ্টা করেছি আমার হিংসার জন্য আমাদের প্রিয় ছেলেকে খুঁজতে, ঈশ্বর তাকে জিজ্ঞেস করেছেন, তিনি তার জীবনের শপথে যাবেন। অথবা কতজন? সে বলেছে.","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏ثَوْرٍ ‏ ‏عَنْ ‏ ‏أَبِي الْغَيْثِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الْعَرَقَ يَوْمَ الْقِيَامَةِ لَيَذْهَبُ فِي الْأَرْضِ سَبْعِينَ ‏ ‏بَاعًا ‏ ‏وَإِنَّهُ لَيَبْلُغُ إِلَى ‏ ‏أَفْوَاهِ النَّاسِ ‏ ‏أَوْ إِلَى آنَافِهِمْ شَكَّ ‏ ‏ثَوْرٌ ‏ ‏بِأَيِّهِمَا قَالَ ‏","","",""],[9059,9059,"","আমরা একটি সুখী ছেলেকে মারতে চেষ্টা করেছি, যে আমার বাবার জন্য কথা বলেছে। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি বলবেন আমি কি করতে চাই, আমি ঋণ-পয়সা-পের বিনিময়ে আটকে আছি।","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏أَبِي سُهَيْلِ بْنِ أَبِي مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا أُحِبُّ أَنَّ عِنْدِي ‏ ‏أُحُدًا ‏ ‏ذَهَبًا يَأْتِي عَلَيَّ ثَالِثَةٌ وَعِنْدِي مِنْهُ شَيْءٌ إِلَّا شَيْءٌ ‏ ‏أَرْصُدُهُ ‏ ‏فِي قَضَاءِ دَيْنٍ يَكُونُ عَلَيَّ ‏","","",""],[9060,9060,"","আমরা একটা সুখী দম্পতি লিখতে চেষ্টা করেছি, যার আগে আমরা অন্ত্যেষ্টিক্রিয়ার আগে একটা ভাল বিষয় আমার বাবা ছিল, ঈশ্বর আদেশ দিয়েছেন যে ঈশ্বর তাকে ক্ষমা করবেন এবং এই অশুভ প্রতারনাকে আত্মসমর্পণ করবেন আত্মার পাপ।","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْإِمَامُ ضَامِنٌ وَالْمُؤَذِّنُ مُؤْتَمَنٌ فَأَرْشَدَ اللَّهُ الْأَئِمَّةَ وَغَفَرَ لِلْمُؤَذِّنِينَ ‏","","",""],[9061,9061,"","আর এই যে , ভাববাদী প্রার্থনা করেছেন তার কাছে আর তার অন ্ তরের আত্মার গৌরব নিয়ে আসবেন । আর প ্ রত ্ যেক সত ্ ত ্ বা জানে যা সে অর ্ জন করেছে , আর তার অন ্ তরের মাঝে আছে ন ্ যায়ের মৃত ্ যু । আর প ্ রত ্ যেক সত ্ ত ্ বা জানে যা সে অর ্ জন করেছে , আর তার অন ্ তরের মাঝে আছে ন ্ যায়ের মৃত ্ যু । আর প ্ রত ্ যেক সত ্ ত ্ বা জানে যা সে অর ্ জন করেছে , আর তার অন ্ তরের মাঝে আছে ন ্ যায়ের মৃত ্ যু । আর প ্ রত ্ যেক সত ্ ত ্ বা জানে যা সে অর ্ জন করেছে , আর তার অন ্ তরের মাঝে আছে ন ্ যায়ের মৃত ্ যু । আত্মার আত্মার আত্মার আত্মার আত্মা, যিনি একজন মানুষের সমবেদনার জন্য দায়ী ।","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِلصَّائِمِ فَرْحَتَانِ فَرْحَةٌ حِينَ يُفْطِرُ وَفَرْحَةٌ حِينَ يَلْقَى رَبَّهُ عَزَّ وَجَلَّ ‏","","",""],[9062,9062,"","আমরা আমার বাবাকে ঈশ্বরের কাছে হস্তান্তরের কথা বলেছি। তার শান্তি ছিল তার মুক্তির এক মহান প্রতিভা এবং তারপর সে অবিশ্বাস্য অবিশ্বাস্য অবিশ্বাস্য ভাবে অবিশ্বাস্য ভাবে সৃষ্টি হল। অথবা সে তাকে শান্ত করতে রাজি হবে, তাই তাকে ঈশ্বরে বিশ্বাস করতে হবে না বা ঈশ্বরে বিশ্বাস করতে হবে না, পুরুষের চাচাই হবে সর্বশ্রেষ্ঠ মানুষের বিশ্ব, মানুষের মায়ের সন্তান। মানুষের আত্মা মানুষের কানেই ঘুমাবে.","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏سُهَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ عَلَى ‏ ‏حِرَاءٍ ‏ ‏هُوَ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏وَعُثْمَانُ ‏ ‏وَعَلِىٌّ ‏ ‏وَطَلْحَةُ ‏ ‏وَالزُّبَيْرُ ‏ ‏فَتَحَرَّكَتْ الصَّخْرَةُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اهْدَأْ فَمَا عَلَيْكَ إِلَّا نَبِيٌّ أَوْ صِدِّيقٌ أَوْ شَهِيدٌ وَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ نِعْمَ الرَّجُلُ ‏ ‏أَبُو بَكْرٍ ‏ ‏نِعْمَ الرَّجُلُ ‏ ‏عُمَرُ ‏ ‏نِعْمَ الرَّجُلُ ‏ ‏أَبُو عُبَيْدَةَ بْنُ الْجَرَّاحِ ‏ ‏نِعْمَ الرَّجُلُ ‏ ‏أُسَيْدُ بْنُ حُضَيْرٍ ‏ ‏نِعْمَ الرَّجُلُ ‏ ‏ثَابِتُ بْنُ قَيْسِ بْنِ شَمَّاسٍ ‏ ‏نِعْمَ الرَّجُلُ ‏ ‏مُعَاذُ بْنُ جَبَلٍ ‏ ‏نِعْمَ الرَّجُلُ ‏ ‏مُعَاذُ بْنُ عَمْرِو بْنِ الْجَمُوحِ ‏","","",""],[9063,9063,"","আমরা একটা বাপ্তিস্মের ছেলের অনুগ্রহে আমাদের খুন করার চেষ্টা করেছি, তার মানে আমার ছেলের প্রতিভার অধিকারী। আমার বাবা তার কাছে প্রার্থনা করেছেন যে তিনি আত্মসমর্পণ করেছেন সে ঈশ্বরের কাছে ফিরে যাবে, আমি দরজা বন্ধ করে দেই, সে এমনকি এটা খেতেও পারে নি। সে বলল যে, সে নাকি ঘরে ঢুকে গেছে। তারপর লোকটি সীমা ভেঙ্গেছে। আর সে বলেছে, আমরা সেই লোক যাকে বলেছিলাম, আমরা সেই লোক। সে তোমাকে আর ঈশ্বর বলে দিয়েছে। মৃত্যুর রাজা, সে ঈশ্বরের অনুগ্রহে পার হতে চেয়েছিল, সে তার জায়গাকে অনুভব করতে চেয়েছিল যাতে সে তার হাত ধরে তাকে মারতে পারে, তার হাত ধরে রাখার জন্য আমি তাকে খুন করবো, আমি শুয়ে থাকব। একজন অপরাধী আমার বাবা একজন ভালো যাজক যে ঈশ্বরের কাছে প্রার্থনা করবে, ঈশ্বরের দোহাই আর শান্তির জন্য, ঈশ্বরের ইচ্ছা হল সে আত্মসমর্পণ করেছে আর তাকে কল্পনার সাথে সেবা করেছে।","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ مُحَمَّدٍ يَعْنِي الْقَارِيَّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَبِي عَمْرٍو ‏ ‏عَنِ ‏ ‏الْمُطَّلِبِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏دَاوُدُ ‏ ‏النَّبِيُّ فِيهِ غَيْرَةٌ شَدِيدَةٌ وَكَانَ إِذَا خَرَجَ أُغْلِقَتْ الْأَبْوَابُ فَلَمْ يَدْخُلْ عَلَى أَهْلِهِ أَحَدٌ حَتَّى يَرْجِعَ قَالَ فَخَرَجَ ذَاتَ يَوْمٍ وَغُلِّقَتْ الدَّارُ فَأَقْبَلَتْ امْرَأَتُهُ تَطَّلِعُ إِلَى الدَّارِ فَإِذَا رَجُلٌ قَائِمٌ وَسَطَ الدَّارِ فَقَالَتْ لِمَنْ فِي الْبَيْتِ مِنْ أَيْنَ دَخَلَ هَذَا الرَّجُلُ الدَّارَ وَالدَّارُ مُغْلَقَةٌ وَاللَّهِ ‏ ‏لَتُفْتَضَحُنَّ ‏ ‏بِدَاوُدَ ‏ ‏فَجَاءَ ‏ ‏دَاوُدُ ‏ ‏فَإِذَا الرَّجُلُ قَائِمٌ وَسَطَ الدَّارِ فَقَالَ لَهُ ‏ ‏دَاوُدُ ‏ ‏مَنْ أَنْتَ قَالَ أَنَا الَّذِي لَا أَهَابُ الْمُلُوكَ وَلَا يَمْتَنِعُ مِنِّي شَيْءٌ فَقَالَ ‏ ‏دَاوُدُ ‏ ‏أَنْتَ وَاللَّهِ مَلَكُ الْمَوْتِ فَمَرْحَبًا بِأَمْرِ اللَّهِ ‏ ‏فَرَمَلَ ‏ ‏دَاوُدُ ‏ ‏مَكَانَهُ حَيْثُ قُبِضَتْ رُوحُهُ حَتَّى فَرَغَ مِنْ شَأْنِهِ وَطَلَعَتْ عَلَيْهِ الشَّمْسُ فَقَالَ ‏ ‏سُلَيْمَانُ ‏ ‏لِلطَّيْرِ أَظِلِّي عَلَى ‏ ‏دَاوُدَ ‏ ‏فَأَظَلَّتْ عَلَيْهِ الطَّيْرُ حَتَّى أَظْلَمَتْ عَلَيْهِمَا الْأَرْضُ فَقَالَ لَهَا ‏ ‏سُلَيْمَانُ ‏ ‏اقْبِضِي جَنَاحًا جَنَاحًا قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏يُرِينَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَيْفَ فَعَلَتْ الطَّيْرُ وَقُبِضَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَغَلَبَتْ عَلَيْهِ يَوْمَئِذٍ ‏ ‏الْمَصْرَخِيَّةُ ‏","","",""],[9064,9064,"","আমরা একটি সুখী ছেলেকে লিখতে চেষ্টা করেছি, যে আমাদের সাথে কথা বলেছে কিন্তু আমি ক্ষমার সন্তান। আমার বাবা এমন এক উপহার যা তার কাছে প্রার্থনা করে, যা ঈশ্বর তাঁর কাছে প্রার্থনা করে থাকেন এবং তাকে কোন প্রতারণা ছাড়াই পরাজিত করা হবে না। মনে হয় তুমি এটা জিততে পারবে... ...না যতক্ষণ না তুমি একই জিনিস পাবে.","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَعْقُوبُ يَعْنِي ابْنَ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَتَصَدَّقُ أَحَدٌ بِتَمْرَةٍ مِنْ كَسْبٍ طَيِّبٍ إِلَّا أَخَذَهَا اللَّهُ بِيَمِينِهِ يُرَبِّيهَا لَهُ كَمَا يُرَبِّي أَحَدُكُمْ ‏ ‏فَلُوَّهُ ‏ ‏أَوْ ‏ ‏فَصِيلَهُ ‏ ‏حَتَّى تَكُونَ لَهُ مِثْلَ الْجَبَلِ أَوْ أَعْظَمَ ‏","","",""],[9065,9065,"","ঈশ্বর যদি তার জন্য প্রার্থনা করেন, তাহলে তিনি প্রভু এবং প্রভু তাকে জয়ের কথা ভুলে যাবেন না। আমি একজন বিজয়ী ছিলাম এবং আমি প্রার্থনা করতে পারি অথবা অনুভব করতে পারি লোকজন আমার বালতি।","‏ ‏وَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يُبْغِضُ ‏ ‏الْأَنْصَارَ ‏ ‏رَجُلٌ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ وَلَوْلَا الْهِجْرَةُ لَكُنْتُ امْرَأً مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏وَلَوْ سَلَكَتْ ‏ ‏الْأَنْصَارُ ‏ ‏وَادِيًا ‏ ‏أَوْ ‏ ‏شِعْبًا ‏ ‏لَسَلَكْتُ وَادِيَهُمْ ‏ ‏أَوْ ‏ ‏شِعْبَهُمْ ‏ ‏الْأَنْصَارُ ‏ ‏شِعَارِي وَالنَّاسُ ‏ ‏دِثَارِي ‏","","",""],[9066,9066,"","( ১ করিন্থীয় ১৫: ৩৩) আর তিনি ঈশ্বরকে এমন কিছু থেকে বের হতে বলেন, যা তিনি স্পর্শ ও দোষ ও দোষারোপ করতে চেয়েছিলেন ।","‏ ‏وَبِإِسْنَادِهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ لُبْسَتَيْنِ ‏ ‏الصَّمَّاءِ ‏ ‏وَأَنْ ‏ ‏يَحْتَبِيَ ‏ ‏الرَّجُلُ بِثَوْبِهِ لَيْسَ عَلَى فَرْجِهِ مِنْهُ شَيْءٌ وَعَنْ ‏ ‏الْمُلَامَسَةِ ‏ ‏وَالْمُنَابَذَةِ ‏ ‏وَالْمُحَاقَلَةِ ‏ ‏وَالْمُزَابَنَةِ ‏","","",""],[9067,9067,"","আর ঈশ্বর তার জন্য প্রার্থনা করেছেন আর তিনি আমাকে আত্মসমর্পণ করবেন, প্রথমে তিনি বলেন আমরা রাজা। তিনি আমাকে ফোন করার জন্য তিনি আমাকে ফোন করবেন। এমনকি আমিও স্লাইডও করেন না। যতক্ষণ না সে আঘাত করছে.","‏ ‏وَأَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَنْزِلُ اللَّهُ عَزَّ وَجَلَّ إِلَى السَّمَاءِ الدُّنْيَا كُلَّ لَيْلَةٍ حِينَ ‏ ‏يَمْضِي ثُلُثُ اللَّيْلِ الْأَوَّلُ فَيَقُولُ ‏ ‏أَنَا الْمَلِكُ مَرَّتَيْنِ مَنْ ذَا الَّذِي يَدْعُونِي فَأَسْتَجِيبَ مَنْ الَّذِي يَسْأَلُنِي فَأُعْطِيَهُ مَنْ ذَا الَّذِي يَسْتَغْفِرُنِي فَأَغْفِرَ لَهُ فَلَا يَزَالُ كَذَلِكَ حَتَّى يُضِيءَ الْفَجْرُ ‏","","",""],[9068,9068,"","আমরা ঈশ্বরের সাথে কথা বলেছি একটা ভুল কথা শোনার জন্য, বাবা আমার ভাইয়ের নাম নিয়ে উড়ে যাচ্ছে, ঈশ্বর দাবি করছে যে চোর হিসেবে তৃতীয়বারের মত আগুনের গন্ধ হারিয়েছে হয়তো, ছয় বছর ধরে আমি আর দশ বছর ধরে কোন বন্দী থাকিনি আর এমন একটা গল্প শুনতে পাই যা প্রতি বছর এক বছর বা এক বছর।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏حَفْصُ بْنُ غِيَاثِ بْنِ طَلْقِ بْنِ مُعَاوِيَةَ النَّخَعِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏طَلْقَ بْنَ مُعَاوِيَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا زُرْعَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ امْرَأَةً أَتَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِصَبِيٍّ لَهَا فَقَالَتْ يَا رَسُولَ اللَّهِ ‏ ‏ادْعُ اللَّهَ لَهُ فَقَدْ دَفَنْتُ ثَلَاثَةً فَقَالَ لَقَدْ ‏ ‏احْتَظَرْتِ ‏ ‏بِحِظَارٍ ‏ ‏شَدِيدٍ مِنْ النَّارِ ‏ ‏قَالَ ‏ ‏حَفْصٌ ‏ ‏سَمِعْتُ هَذَا الْحَدِيثَ مِنْ سِتِّينَ سَنَةً وَلَمْ أَبْلُغْ ‏ ‏عَشْرَ سِنِينَ وَسَمِعْتُ ‏ ‏حَفْصًا ‏ ‏يَذْكُرُ هَذَا الْكَلَامَ سَنَةَ سَبْعٍ وَثَمَانِينَ وَمِائَةٍ ‏","","",""],[9069,9069,"","আমরা ঈশ্বরের একজন বেপটিস্ট হওয়ার কথা বলেছিলাম, যে বলেছে যে ঈশ্বর হয়ত শুনেছেন যে আমি ঈশ্বরের পর্দা থেকে এসেছি। আমরা আমার বাবার সাথে কথা বলেছি যে শীঘ্রই তিনি একটি ছেলের মুক্তির জন্য একটি উপহার প্রদান করবেন। এমন একজন পুত্র যে হবে সন্তান যে পুত্র সন্তান হবে, সে এমন একজন সন্তান হবে যে সন্তান সন্তান হবে, যে এমন একজন পুরুষ হবে, যে একজন পুরুষ হবে, সে হবে এমন লোক, যে হবে একজন পুরুষ হবে মানুষ । মানুষ এমন একজন মানুষ মানুষ মানুষ হবে মানুষ মানুষ মানুষ হবে হবে মানুষ মানুষ মানুষ মানুষ মানুষ হবে হবে হবে যদি সে এমন একজন মানুষ মানুষ মানুষ মানুষ মানুষ হবে মানুষ মানুষ হবে যে মানুষ মানুষ মানুষ হবে মানুষ মানুষ মানুষ হবে হবে মানুষ মানুষ মানুষ মানুষ মানুষ মানুষ হয়ে থাকবে । যে লোক পুরুষ হোক সে হবে মানুষ যে মানুষ পুরুষ হোক , সে হবে একজন মানুষ , যে মানুষ মানুষ হয়ে থাকবে , সে এমন একজন মানুষ যে হবে , সে এমন লোক যে হবে যে মানুষ মানুষ । মানুষ এমন একজন মানুষ মানুষ মানুষ হবে মানুষ মানুষ মানুষ হবে হবে মানুষ মানুষ মানুষ মানুষ মানুষ হবে হবে হবে যদি সে এমন একজন মানুষ মানুষ মানুষ মানুষ মানুষ হবে মানুষ মানুষ হবে যে মানুষ মানুষ মানুষ হবে মানুষ মানুষ মানুষ হবে হবে মানুষ মানুষ মানুষ মানুষ মানুষ মানুষ হয়ে থাকবে । যে লোক পুরুষ হোক সে হবে একজন মানুষ যে মানুষ যে কিনা কিনা তাকে একজন পুরুষ মানুষ হিসেবে বিবেচনা করবে। ( মথি ৫: ৩) কিন্তু, এই ধরনের এক মন্দ আকাঙ্ক্ষার দ্বারা প্রভাবিত হওয়ার জন্য ঈশ্বর তাকে সাহায্য করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ بْن أَحْمَد ‏ ‏و سَمِعْت ‏ ‏أَنَا مِنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ أَبِي شَيْبَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو خَالِدٍ الْأَحْمَرُ ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا ‏ ‏جُعِلَ الْإِمَامُ ‏ ‏لِيُؤْتَمَّ ‏ ‏بِهِ فَإِذَا كَبَّرَ فَكَبِّرُوا وَإِذَا قَرَأَ فَأَنْصِتُوا ‏","","",""],[9070,9070,"","আমার বাবা একজন উৎপীড়ক ছিলেন, যিনি তার কাছে প্রার্থনা করেছিলেন এবং তাকে আনন্দে উদ্ধার করেছেন এবং আমাকে একটা ফোন করেছেন ব্যর্থ.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ بْن أَحْمَد ‏ ‏وَسَمِعْتُهُ أَنَا ‏ ‏مِنْهُ ‏ ‏حَدَّثَنَا ‏ ‏حَفْصُ بْنُ غِيَاثٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ ‏ ‏بِسَعْدٍ ‏ ‏وَهُوَ يَدْعُو فَقَالَ أَحِّدْ أَحِّدْ ‏","","",""],[9071,9071,"","ঈশ্বর যদি বিজ্ঞান লোকেদের পরিচালনা করার জন্য ধনী হতেন, তা হলে তিনি তাকে একজন উৎপীড়ক হিসেবে তুলে ধরেছিলেন । ফারেস।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ بْنُ عَطَاءٍ ‏ ‏أَخْبَرَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏قَالَ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ كَانَ الْعِلْمُ ‏ ‏بِالثُّرَيَّا ‏ ‏لَتَنَاوَلَهُ نَاسٌ مِنْ ‏ ‏أَهْلِ ‏ ‏فَارِسَ ‏","","",""],[9072,9072,"","আমার বাবার সাথে কথা বলার সময় আমরা আমার বাবার সাথে কথা বলেছিলাম, ভাল ছেলে যে আমাকে বলতে পারবে ঈশ্বর এসেছে, ঈশ্বর জানেন এটা ঈশ্বরের জীবন। আমার বাবার ভালো মানুষ হওয়ার কথা জানো, আমি তার জীবন ব্যয় করেছি একজন অগ্নিমানব হিসেবে... ...সে বলেছে যে তাকে মুক্ত হতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏مَكِّيُّ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ سَعِيدِ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أَبِي حَكِيمٍ ‏ ‏مَوْلَى آلِ ‏ ‏الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏سَعِيدِ ابْنِ مَرْجَانَةَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَعْتَقَ رَقَبَةً مُؤْمِنَةً أَعْتَقَ اللَّهُ بِكُلِّ ‏ ‏إِرْبٍ ‏ ‏مِنْهُ ‏ ‏إِرْبًا ‏ ‏مِنْ النَّارِ حَتَّى أَنَّهُ لَيَعْتِقُ بِالْيَدِ الْيَدَ وَبِالرِّجْلِ الرِّجْلَ وَبِالْفَرْجِ الْفَرْجَ ‏ ‏فَقَالَ ‏ ‏عَلِيُّ بْنُ حُسَيْنٍ ‏ ‏أَنْتَ سَمِعْتَ هَذَا مِنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏فَقَالَ ‏ ‏سَعِيدٌ ‏ ‏نَعَمْ فَقَالَ ‏ ‏عَلِىُّ بْنُ حُسَيْنٍ ‏ ‏لِغُلَامٍ لَهُ أَفْرَهَ غِلْمَانِهِ ادْعُ لِي ‏ ‏مُطَرِّيًا ‏ ‏قَالَ فَلَمَّا قَامَ بَيْنَ يَدَيْهِ قَالَ اذْهَبْ فَأَنْتَ حُرٌّ لِوَجْهِ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[9073,9073,"","আমরা কথা বলেছিলাম কি ভাবে আমার বাবা ঈশ্বরকে বলতে গেলে তাঁর জন্ম হয়েছিল। আল্লাহকে একটা ভাল জীবন দিতে হবে এবং ক্ষমা করতে হবে। একটি অন্ত্যেষ্টিক্রিয়া এবং এটা একটা চোখ এবং অপহরণ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْلَمُ ‏ ‏وَغِفَارٌ ‏ ‏وَشَيْءٌ مِنْ ‏ ‏جُهَيْنَةَ ‏ ‏وَمُزَيْنَةَ ‏ ‏خَيْرٌ عِنْدَ اللَّهِ يَوْمَ الْقِيَامَةِ مِنْ ‏ ‏تَمِيمٍ ‏ ‏وَأَسَدِ بْنِ خُزَيْمَةَ ‏ ‏وَهَوَازِنَ ‏ ‏وَغَطَفَانَ ‏","","",""],[9074,9074,"","আমরা একটা মোজ নিয়ে কথা বলেছি, যা আমরা করেছি তার চেয়ে ভালো হয়েছে। তিনি বলেছিলেন, ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং তিনি স্বর্গের কাছে আত্মসমর্পণ করবেন প্রভুর অনুগ্রহ থেকে তাদের অদ্ভুত শক্তিগুলো দেখতে।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نِسَاءُ أَهْلِ الْجَنَّةِ يُرَى مُخُّ سُوقِهِنَّ مِنْ وَرَاءِ اللَّحْمِ ‏","","",""],[9075,9075,"","ঈশ্বর তাকে ঈশ্বর আমার কাছে এই কথা বলেছিলেন যে, ঈশ্বর হয়তো তাকে বলতে শুনেছেন যে, আমরা যা করছি, তা ঈশ্বর শুনতে পান । ( ২ শমূ.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ بْن أَحْمَد ‏ ‏وَسَمِعْتُهُ أَنَا ‏ ‏مِنْهُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَحَبَّ لِقَاءَ اللَّهِ أَحَبَّ اللَّهُ لِقَاءَهُ وَمَنْ كَرِهَ لِقَاءَ اللَّهِ كَرِهَ اللَّهُ لِقَاءَهُ ‏","","",""],[9076,9076,"","আমরা এটা জেনে কথা বলেছিলাম যে আমরা একটা ভালো ছেলে হয়ে যাবো, সে বলল যে সে ঈশ্বরের কাছে শান্তি চায়, আর সে মুক্ত হবে না।","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَعْرُوفُ بْنُ سُوَيْدٍ الْجُذَامِيُّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَلِيَّ بْنَ رَبَاحٍ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏عَدْوَى ‏ ‏وَلَا ‏ ‏طِيَرَةَ ‏ ‏وَالْعَيْنُ ‏ ‏حَقٌّ ‏","","",""],[9077,9077,"","আমরা আমাদের বাবার সাথে তোমার সম্পর্কে কথা বলেছিলাম, বাবা হারপারের সাথে কথা বলতে শুনেছি, তার শান্তি আছে আর সে বলবে যে সে খেলায় নেই.","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏حَدَّثَنَا ‏ ‏مَخْرَمَةُ بْنُ بُكَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عِرَاكِ بْنِ مَالِكٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَيْسَ فِي الْعَبْدِ ‏ ‏صَدَقَةٌ ‏ ‏إِلَّا ‏ ‏صَدَقَةَ ‏ ‏الْفِطْرِ ‏","","",""],[9078,9078,"","আমরা আমার বাবা সম্পর্কে কথা বলেছি যে তিনি ঈশ্বরকে কিছু হিংসা করতেন। তারা গান গাইতে এবং তোমার দৃষ্টি উপভোগ করতে জোর করতো না। তোমার বোনের সাথে লড়াই কর, আর তোমার কিছু জিনিস বিক্রি করো না।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏تُصَرُّوا ‏ ‏الْإِبِلَ وَالْغَنَمَ فَمَنْ ‏ ‏ابْتَاعَ ‏ ‏مُصَرَّاةً ‏ ‏فَهُوَ بِآخِرِ ‏ ‏النَّظَرَيْنِ ‏ ‏إِنْ شَاءَ أَمْسَكَهَا وَإِنْ شَاءَ رَدَّهَا ‏ ‏بِصَاعٍ ‏ ‏مِنْ تَمْرٍ وَلَا تَسْأَلْ الْمَرْأَةُ طَلَاقَ أُخْتِهَا وَلَا ‏ ‏تَنَاجَشُوا ‏ ‏وَلَا يَبِعْ بَعْضُكُمْ عَلَى بَيْعِ بَعْضٍ وَلَا يَبِعْ حَاضِرٌ ‏ ‏لِبَادٍ ‏","","",""],[9079,9079,"","আমরা একটা ছেলে বলতে চেষ্টা করেছি আর আমি বলবো যে কিভাবে আমাকে ভালবাসার জন্য বেঁচে থাকতে বলা যায়, ঈশ্বর তার কথা শুনেছেন... কে মরুউমের মধ্যে আছে, সে বলছে খোদা তোমাদের কাছে নেই।","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏ابْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏حَيْوَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ اللَّهِ ‏ ‏مَوْلَى ‏ ‏شَدَّادِ بْنِ الْهَادِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ سَمِعَ رَجُلًا ‏ ‏يَنْشُدُ ‏ ‏فِي الْمَسْجِدِ ‏ ‏ضَالَّةً ‏ ‏فَلْيَقُلْ لَا أَدَّاهَا اللَّهُ عَلَيْكَ فَإِنَّ الْمَسَاجِدَ لَمْ تُبْنَ لِذَلِكَ ‏","","",""],[9080,9080,"","আমরা একটি ছেলে থাকার কথা বলেছি এবং আমি আমার ছেলেকে রক্ষা করার কথা একবার শুনতে চাই। সে তার বাবার কথা শুনে, যে বলল সে ঈশ্বরকে প্রার্থনা করে, সে কখনো বলে নি, পানি সব টাকা ফেলে চোখকে ফেরত দিতে পারবে না।","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏حَيْوَةَ ‏ ‏يَقُولُ حَدَّثَنِي ‏ ‏حُمَيْدُ بْنُ هَانِئٍ الْخَوْلَانِيُّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏غِفَارَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تَبِيعُوا ‏ ‏فَضْلَ ‏ ‏الْمَاءِ وَلَا تَمْنَعُوا ‏ ‏الْكَلَأَ ‏ ‏فَيَهْزُلَ الْمَالُ وَيَجُوعَ الْعِيَالُ ‏","","",""],[9081,9081,"","আমরা কথা বলেছিলাম, হারোণের জন্ম হয়েছে দেয়ালের নিচে শিকার করার জন্য। আমার বাবা ঈশ্বরের অনুগ্রহের জন্য উপহার, ঈশ্বর তাকে আদেশ দিয়েছেন আর তিনি বললেন যে তিনি অনেক পুরানো। আর তিনি যুদ্ধ করতে চান। আমি জানি, আমি জানি, আমি জানি না, আমি কি করতে পারি? চাঁদ","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏حَيْوَةَ ‏ ‏عَنِ ‏ ‏ابْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ بْنِ الْحَارِثِ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ إِنْ كَانَ قَالَهُ ‏ ‏جِهَادُ الْكَبِيرِ وَالضَّعِيفِ وَالْمَرْأَةِ الْحَجُّ وَالْعُمْرَةُ ‏","","",""],[9082,9082,"","আমরা কথা বলেছি আর আমরা কথা বলেছি আর আমাকে বলতে যে সাগর আমাকে সাহায্য করার চেষ্টা করছে, হয়তো আমার বাবার ব্যাপারে তাকে দেখানোর সবচেয়ে ভালো উপায় হল তিনি যে ঈশ্বরের ইচ্ছার সাথে মিল রেখে গেছেন তার শান্তি.","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ الْحَارِثِ التَّيْمِيُّ ‏ ‏أَنَّ ‏ ‏جَعْفَرَ بْنَ رَبِيعَةَ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏عَبْدَ الرَّحْمَنِ الْأَعْرَجَ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏هَامَ ‏ ‏لَا ‏ ‏هَامَ ‏","","",""],[9083,9083,"","আমার নাম আমার বাবা, তার বাবার অনেক কথা শুনে আমার বাবা - মা অনেক কিছু শুনেছিলেন । ঈশ্বর আছে আর আমি বলে দিবো যে ঈশ্বরের পরবর্তী অংশ আর কথা বলার জন্য যথেষ্ট।","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَسَمِعْتُهُ أَنَا مِنْ ‏ ‏هَارُونَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ غَزِيَّةَ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏مَوْلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا صَالِحٍ ذَكْوَانَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَقْرَبُ مَا يَكُونُ الْعَبْدُ مِنْ رَبِّهِ وَهُوَ سَاجِدٌ فَأَكْثِرُوا الدُّعَاءَ ‏","","",""],[9084,9084,"","আমরা একটি ছেলে ছেলে থাকার কথা বলেছিলাম এবং আমাকে একটা ছেলে সম্পর্কে বলতে হবে যে, তাকে ছেলে বলতে হবে। আমি ঈশ্বরকে দেখতে সক্ষম হব, আল্লাহ আছে, আর তিনি এটা করবেন যে আপনি অপেক্ষা করতে পারবেন না। ঈশ্বর ক্ষমা করুন ।","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنِ ‏ ‏ابْنِ هُرْمُزَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ أَحَدَكُمْ مَا قَعَدَ يَنْتَظِرُ الصَّلَاةَ فِي صَلَاةٍ مَا لَمْ يُحْدِثْ تَدْعُو لَهُ الْمَلَائِكَةُ اللَّهُمَّ اغْفِرْ لَهُ اللَّهُمَّ ارْحَمْهُ ‏","","",""],[9085,9085,"","আমরা হারোণের সাথে কথা বলেছি এবং গরমের মধ্য দিয়ে চলে যাচ্ছি। আমার বাবা তাকে এটা বলতে শিখিয়েছিলেন যে, সে কখনোই ঈশ্বরের কাছে ফিরে যায়নি। আমি অনেক মানুষ। আমি জানি, আমি জানি, আমি কি বলেছি, আমি এটা করতে পারি? অনেক মানুষ যারা চলে যাচ্ছে.","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَمْرُو بْنُ الْحَارِثِ ‏ ‏أَنَّ ‏ ‏أَبَا يُونُسَ ‏ ‏مَوْلَى ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَا أَنْزَلَ اللَّهُ عَزَّ وَجَلَّ مِنْ السَّمَاءِ بَرَكَةً إِلَّا أَصْبَحَ كَثِيرٌ مِنْ النَّاسِ بِهَا كَافِرِينَ يُنَزِّلُ اللَّهُ عَزَّ وَجَلَّ ‏ ‏الْغَيْثَ ‏ ‏فَيَقُولُونَ بِكَوْكَبِ كَذَا وَكَذَا ‏","","",""],[9086,9086,"","আমরা শপথ নিয়ে কথা বলেছি, আমি বলতে চাই যে আমার কাছে এমন একটা ছেলে আছে যার জন্য আমি কিছু করেছি। একজন মহিলার ভয়ানক উপায়ে সে পালাতে পারে না। আমি একজন হয়ে গেলাম। খারাপ বোকা, তুমি তাকে মারার জন্য এখানে আমাদের কিছু একটা করতে পার, কারণ ঈশ্বর কখনো আমাদের সাথে থাকতে পারে। একজন আমাকে জিতুক যে আমি এখন আমার শিকারে পরিণত হতে চাই। আমি বলব সে বলেছিল। আমি বলব, সে বলেছিল, আমি যদি বলি, \"আমি যদি বলি,\" কিন্তু আমি যদি বলি, \"আমি যদি বলি,\" তুমি আমাকে ছেড়ে দাও, \"আমি যদি তোমার সাথে থাকতে চাই,\" তুমি আমাকে এটা করতে পারো, তাহলে তুমি আমাকে এটা একটা কথা বলতে হবে। আর আমি যদি তোমার কাছে ফিরে যেতে পারি, তাহলে তুমি আমাকে এটা করতে হবে।\" সে যদি উপরে তাকিয়ে থাকে, সে তাকে সান্ত্বনা দেবে, সে মারা যাবে এবং তার আকাশ থেকে বেরিয়ে যাবে। আমার বাবা তার কাছে এসে বলতে পারে যে, সে নাকি একজন হরিণের কাছে এসেছে এবং সে আছে যদি সে যা করে তা নিয়ে নেয় এবং তা নিতে পারবে না ।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ يَعْنِي ابْنَ بَهْرَامَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَهْرُ بْنُ حَوْشَبٍ ‏ ‏قَالَ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏بَيْنَمَا رَجُلٌ وَامْرَأَةٌ لَهُ فِي ‏ ‏السَّلَفِ ‏ ‏الْخَالِي لَا يَقْدِرَانِ عَلَى شَيْءٍ فَجَاءَ الرَّجُلُ مِنْ سَفَرِهِ فَدَخَلَ عَلَى امْرَأَتِهِ جَائِعًا قَدْ أَصَابَتْهُ ‏ ‏مَسْغَبَةٌ ‏ ‏شَدِيدَةٌ فَقَالَ لِامْرَأَتِهِ أَعِنْدَكِ شَيْءٌ قَالَتْ نَعَمْ أَبْشِرْ أَتَاكَ رِزْقُ اللَّهِ فَاسْتَحَثَّهَا فَقَالَ ‏ ‏وَيْحَكِ ‏ ‏ابْتَغِي إِنْ كَانَ عِنْدَكِ شَيْءٌ قَالَتْ نَعَمْ ‏ ‏هُنَيَّةً ‏ ‏نَرْجُو رَحْمَةَ اللَّهِ حَتَّى إِذَا طَالَ عَلَيْهِ ‏ ‏الطَّوَى ‏ ‏قَالَ ‏ ‏وَيْحَكِ ‏ ‏قُومِي فَابْتَغِي إِنْ كَانَ عِنْدَكِ خُبْزٌ فَأْتِينِي بِهِ فَإِنِّي قَدْ ‏ ‏بَلَغْتُ ‏ ‏وَجَهِدْتُ فَقَالَتْ نَعَمْ الْآنَ يَنْضَجُ ‏ ‏التَّنُّورُ ‏ ‏فَلَا تَعْجَلْ فَلَمَّا أَنْ سَكَتَ عَنْهَا سَاعَةً وَتَحَيَّنَتْ أَيْضًا أَنْ يَقُولَ لَهَا قَالَتْ هِيَ مِنْ عِنْدِ نَفْسِهَا لَوْ قُمْتُ فَنَظَرْتُ إِلَى ‏ ‏تَنُّورِي ‏ ‏فَقَامَتْ فَوَجَدَتْ ‏ ‏تَنُّورَهَا ‏ ‏مَلْآنَ جُنُوبَ الْغَنَمِ وَرَحْيَيْهَا تَطْحَنَانِ فَقَامَتْ إِلَى ‏ ‏الرَّحَى ‏ ‏فَنَفَضَتْهَا وَأَخْرَجَتْ مَا فِي تَنُّورِهَا مِنْ جُنُوبِ الْغَنَمِ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏فَوَالَّذِي نَفْسُ ‏ ‏أَبِي الْقَاسِمِ ‏ ‏بِيَدِهِ عَنْ قَوْلِ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ أَخَذَتْ مَا فِي رَحْيَيْهَا وَلَمْ تَنْفُضْهَا لَطَحَنَتْهَا إِلَى يَوْمِ الْقِيَامَةِ ‏","","",""],[9087,9087,"","আমরা আমাদের বাবার আর তার প্রেমিকের জন্য একটা চমকের চেয়ে অনেক ভালো কাজ করেছি, আমার বাবার ইচ্ছা, ঈশ্বরের জয় তার উপর এসে পৌঁছে গেছে। ভালবাসা আর বোঝার ক্ষমতা, সে এই বাস্তবতা থেকে বেরিয়ে গেছে যে তার কিছু বানরকে আমি ঘুষি মারছি। হায় খোদা।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏وَجَعْفَرِ بْنِ أَبِي وَحْشِيَّةَ ‏ ‏وَعَبَّادِ بْنِ مَنْصُورٍ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ عَلَى أَصْحَابِهِ وَهُمْ يَتَنَازَعُونَ فِي الشَّجَرَةِ الَّتِي ‏ ‏اجْتُثَّتْ ‏ ‏مِنْ فَوْقِ الْأَرْضِ مَا لَهَا مِنْ ‏ ‏قَرَارٍ ‏ ‏فَقَالَ بَعْضُهُمْ أَحْسَبُهَا ‏ ‏الْكَمْأَةَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْكَمْأَةُ ‏ ‏مِنْ ‏ ‏الْمَنِّ ‏ ‏وَمَاؤُهَا شِفَاءٌ لِلْعَيْنِ وَالْعَجْوَةُ مِنْ الْجَنَّةِ وَهِيَ شِفَاءٌ لِلسُّمِّ ‏","","",""],[9088,9088,"","আমি আমার বাবাকে বলেছিলাম যে, ঈশ্বর তাকে প্রার্থনা করেছেন এবং তার প্রতি ও তার সিংহাসনের কাছে আমি জয়ী হয়েছি । ঈশ্বর তাকে ব্যর্থ হতে আদেশ দিয়েছেন । আল্লাহ তাকে এবং যারা আল্‌র শোক করেছে তাদের জন্য আল্লাহ তাকে পাঠিয়েছেন, তাদের কাছে এটা অনেক ভালো করেছেন। অপরাধের প্রতি ঈর্ষা","‏ ‏حَدَّثَنَا ‏ ‏فَزَارَةُ بْنُ عَمْرٍو ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏فُلَيْحٌ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غَزْوَةٍ غَزَاهَا ‏ ‏فَأَرْمَلَ ‏ ‏فِيهَا الْمُسْلِمُونَ وَاحْتَاجُوا إِلَى الطَّعَامِ فَاسْتَأْذَنُوا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏نَحْرِ ‏ ‏الْإِبِلِ فَأَذِنَ لَهُمْ فَبَلَغَ ذَلِكَ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏قَالَ فَجَاءَ فَقَالَ يَا رَسُولَ اللَّهِ إِبِلُهُمْ تَحْمِلُهُمْ وَتُبَلِّغُهُمْ عَدُوَّهُمْ يَنْحَرُونَهَا بَلْ ادْعُ يَا رَسُولَ اللَّهِ ‏ ‏بِغَبَرَاتِ ‏ ‏الزَّادِ ‏ ‏فَادْعُ اللَّهَ عَزَّ وَجَلَّ فِيهَا بِالْبَرَكَةِ قَالَ أَجَلْ قَالَ فَدَعَا ‏ ‏بِغَبَرَاتِ ‏ ‏الزَّادِ ‏ ‏فَجَاءَ النَّاسُ بِمَا بَقِيَ مَعَهُمْ فَجَمَعَهُ ثُمَّ دَعَا اللَّهَ عَزَّ وَجَلَّ فِيهِ بِالْبَرَكَةِ وَدَعَا بِأَوْعِيَتِهِمْ فَمَلَأَهَا وَفَضَلَ فَضْلٌ كَثِيرٌ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِنْدَ ذَلِكَ ‏ ‏أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَشْهَدُ أَنِّي عَبْدُ اللَّهِ وَرَسُولُهُ وَمَنْ لَقِيَ اللَّهَ عَزَّ وَجَلَّ بِهِمَا غَيْرَ شَاكٍّ دَخَلَ الْجَنَّةَ ‏","","",""],[9089,9089,"","বাবা যখন আমাকে বলেছিলেন যে, তুমি মারা যাও, তখন আমি তোমাকে হত্যা করতে বলেছিলাম । ঈশ্বরের বলিদানে পরাজিত হয়ে, আমি এটাই বলি, বাবা, আমার প্রতি দয়া করে, এটা হচ্ছে যুদ্ধ যা আমাকে দেখে, সে চলে গেছে। ( গীত.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏بَنِي الْحَارِثِ بْنِ كَعْبٍ ‏ ‏قَالَ ‏ ‏كُنْتُ جَالِسًا عِنْدَ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏فَأَتَاهُ رَجُلٌ فَسَأَلَهُ فَقَالَ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏أَنْتَ نَهَيْتَ النَّاسَ أَنْ يَصُومُوا يَوْمَ الْجُمُعَةِ قَالَ لَا لَعَمْرُ اللَّهِ غَيْرَ أَنِّي وَرَبِّ هَذِهِ الْحُرْمَةِ لَقَدْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَصُومَنَّ أَحَدُكُمْ يَوْمَ الْجُمُعَةِ إِلَّا فِي أَيَّامٍ يَصُومُهُ فِيهَا فَجَاءَ آخَرُ فَقَالَ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏أَنْتَ نَهَيْتَ النَّاسَ أَنْ يُصَلُّوا فِي نِعَالِهِمْ قَالَ لَا لَعَمْرُ اللَّهِ غَيْرَ أَنِّي وَرَبِّ هَذِهِ الْحُرْمَةِ لَقَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي إِلَى هَذَا الْمَقَامِ وَإِنَّ عَلَيْهِ نَعْلَيْهِ ثُمَّ انْصَرَفَ وَهُمَا عَلَيْهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[9090,9090,"","আমরা একটা হাত খেলতে চেষ্টা করেছি, যা আমার ছেলের করা প্রতিশ্রুতির মধ্যে দিয়ে আমি আমার ছেলের সবচেয়ে ভালো দয়া বিক্রি করতে পারি। একটি উপহার শুনলাম যে, ঈশ্বরের কাছে প্রার্থনা করতে শুনেছি, যদি তিনি তার ধ্বংস না করেন। শান্তির ঈশ্বর তাদের ক্ষমা করুন যা ঘটেছে বা কি ঘটে নি, তা নিয়ে তারা ক্ষমা করে দেন।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا صَلَّى أَحَدُكُمْ ثُمَّ جَلَسَ لَمْ تَزَلْ الْمَلَائِكَةُ تَقُولُ اللَّهُمَّ اغْفِرْ لَهُ اللَّهُمَّ ارْحَمْهُ مَا لَمْ يُحْدِثْ أَوْ ‏ ‏يَقُومْ ‏","","",""],[9091,9091,"","আমরা আমার মা'কে সাহায্য করেছি বলে আমরা ঈশ্বরের জীবনের কথা বলেছি। তাহলে সে তার পালকগুলো হারিয়ে ফেলবে, সে জানে না তার পর কী হয়েছে আর তারপর তাকে এটা করতে হবে। আমার কাপুরুষ আর তোমার ছেলে তাকে জাগিয়ে রাখতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ الْأُمَوِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرِ بْنِ حَفْصِ بْنِ عَاصِمٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَتَى أَحَدُكُمْ فِرَاشَهُ فَلْيَنْزِعْ دَاخِلَةَ ‏ ‏إِزَارِهِ ‏ ‏ثُمَّ لِيَنْفُضْ بِهَا فِرَاشَهُ فَإِنَّهُ لَا يَدْرِي مَا حَدَثَ عَلَيْهِ بَعْدَهُ ثُمَّ لِيَضْطَجِعْ عَلَى جَنْبِهِ الْأَيْمَنِ ثُمَّ لِيَقُلْ بِاسْمِكَ رَبِّي وَضَعْتُ جَنْبِي وَبِكَ أَرْفَعُهُ إِنْ ‏ ‏أَمْسَكْتَ ‏ ‏نَفْسِي فَارْحَمْهَا وَإِنْ أَرْسَلْتَهَا فَاحْفَظْهَا بِمَا حَفِظْتَ بِهِ عِبَادَكَ الصَّالِحِينَ ‏","","",""],[9092,9092,"","আমরা একটি ছেলেকে সাহায্য করার চেষ্টা করেছি যে কিনা আমাদের সাহায্য করবে। আমার বাবা সৃষ্টিকর্তা তাকে আত্মসমর্পণ করতে বলেছেন এবং তোমাদের একজনকেও তিনি উদ্ধার করবেন। বাচ্চারা আর কখনো না, চুলে ভালবাসা...","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدِ بْنِ أَبَانَ بْنِ سَعِيدِ بْنِ الْعَاصِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا زَنَتْ خَادِمُ أَحَدِكُمْ فَلْيَجْلِدْهَا وَلَا يُعَيِّرْهَا فَإِنْ عَادَتْ الثَّانِيَةَ فَلْيَجْلِدْهَا وَلَا يُعَيِّرْهَا فَإِنْ عَادَتْ الثَّالِثَةَ فَلْيَجْلِدْهَا وَلَا يُعَيِّرْهَا فَإِنْ عَادَتْ الرَّابِعَةَ فَلْيَجْلِدْهَا وَلْيَبِعْهَا بِحَبْلٍ مِنْ شَعَرٍ ‏ ‏أَوْ بِضَفِيرٍ مِنْ شَعَرٍ ‏","","",""],[9093,9093,"","আমার বাবা ঈশ্বরের কাছে প্রার্থনা করার জন্য একটা উপহার আর তিনি সেই কাজ করার মাধ্যমে শান্তি প্রদান করবেন । তাকে রোষ্ট দাও।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ الْأُمَوِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏خُبَيْبِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏حَفْصِ بْنِ عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الْإِسْلَامَ ‏ ‏لَيَأْرِزُ ‏ ‏إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏كَمَا ‏ ‏تَأْرِزُ ‏ ‏الْحَيَّةُ إِلَى جُحْرِهَا ‏","","",""],[9094,9094,"","আমার ভাই - বোনদের সঙ্গে কথা বলা সত্য হয় ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ الْأُمَوِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْحَجَّاجُ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صُومُوا لِرُؤْيَتِهِ وَأَفْطِرُوا لِرُؤْيَتِهِ فَإِنْ ‏ ‏غُمَّ ‏ ‏عَلَيْكُمْ الشَّهْرُ فَأَكْمِلُوا ‏ ‏الْعِدَّةَ ‏ ‏ثَلَاثِينَ ‏","","",""],[9095,9095,"","বিজ্ঞান যদি ভারুস বিল্ডিং থেকে লোকেদের পরিচালনা করতে ধনী হতো, তা হলে ঈশ্বর তা রক্ষা করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ الْخَفَّافُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏قَالَ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ كَانَ الْعِلْمُ ‏ ‏بِالثُّرَيَّا ‏ ‏لَتَنَاوَلَهُ نَاسٌ مِنْ أَبْنَاءِ ‏ ‏فَارِسَ ‏","","",""],[9096,9096,"","আমরা আমার বাবার কথা বলেছিলাম, পাইলট এমন একটা ছেলেকে সাহায্য করবে যে ঈশ্বরের কাছে পাঠানো হয়েছে। সে বলেছে আমি একটি নিরাপদ ঘাড় ঘৃণা করি যা আল্লাহ্ জানেন। আমার বাবার কাছ থেকে তুমি এটা শুনেছ, সে আমাকে বলেছিল যে, তুমি এটা আমার বাবার কাছ থেকে শুনেছ ।","‏ ‏حَدَّثَنَا ‏ ‏مَكِّيُّ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ سَعِيدِ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أَبِي حَكِيمٍ ‏ ‏مَوْلَى آلِ ‏ ‏الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏سَعِيدِ ابْنِ مَرْجَانَةَ ‏ ‏أَنَّهُ قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَعْتَقَ رَقَبَةً مُؤْمِنَةً أَعْتَقَ اللَّهُ بِكُلِّ ‏ ‏إِرْبٍ ‏ ‏مِنْهَا ‏ ‏إِرْبًا ‏ ‏مِنْهُ مِنْ النَّارِ حَتَّى إِنَّهُ لَيُعْتِقُ بِالْيَدِ الْيَدَ وَبِالرِّجْلِ الرِّجْلَ وَبِالْفَرْجِ الْفَرْجَ ‏ ‏قَالَ ‏ ‏فَقَالَ ‏ ‏عَلِيُّ بْنُ الْحُسَيْنِ ‏ ‏أَنْتَ سَمِعْتَ هَذَا مِنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سَعِيدٌ ‏ ‏نَعَمْ قَالَ ‏ ‏عَلِيُّ بْنُ الْحُسَيْنِ ‏ ‏لِغُلَامٍ لَهُ أَفْرَهُ غِلْمَانِهِ ‏ ‏ادْعُ لِي ‏ ‏مُطْرِبًا ‏ ‏فَلَمَّا قَامَ بَيْنَ يَدَيْهِ قَالَ اذْهَبْ فَأَنْتَ حُرٌّ لِوَجْهِ اللَّهِ تَعَالَى ‏","","",""],[9097,9097,"","আমাদের বাবা কি বলেছেন তা নিয়ে আমাদের কথা বলেছেন। ঈশ্বর আমাকে ভালোর জীবন উদ্ধার এবং ক্ষমা করে দিতে হবে। অন্ত্যেষ্টিক্রিয়ার মাধ্যমে এবং এটা অপহরণ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَسْلَمُ ‏ ‏وَغِفَارُ ‏ ‏وَشَيْءٌ مِنْ ‏ ‏جُهَيْنَةَ ‏ ‏وَمُزَيْنَةَ ‏ ‏خَيْرٌ عِنْدَ اللَّهِ يَوْمَ الْقِيَامَةِ مِنْ ‏ ‏تَمِيمٍ ‏ ‏وَأَسَدِ بْنِ خُزَيْمَةَ ‏ ‏وَهَوَازِنَ ‏ ‏وَغَطَفَانَ ‏","","",""],[9098,9098,"","আমরা একটা মাসোর কথা বলেছি, সে বলল আমরা একটা টোপ তৈরি করেছি। সে বলল, ঈশ্বর তাকে জানতেন আর তিনি আকাশের দিকে তাদের স্টান্টগুলো আত্মসমর্পণ করবেন।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نِسَاءُ أَهْلِ الْجَنَّةِ يُرَى مُخُّ سُوقِهِنَّ مِنْ وَرَاءِ اللَّحْمِ ‏","","",""],[9099,9099,"","আমি আমার বাবার জন্য দুঃখিত, যে আমাকে ঈশ্বরের চোখে প্রার্থনা করার সময় বলেছিল, সে এটা এ. যে কিনা শব্দকে গৌরব প্রদান করেছে, প্রভু, প্রার্থনা করতে ব্যর্থ হয়েছে অথবা ভুলে গেছে খোদা এটা করেছে। তুমি ছোট, আমি তাকে বলতে ভুলে যাইনি, প্রভু, যখন তুমি যেতে এবং বলতে গেলে আল্লাহ্‌কে বলতে গেলে হাত দিয়ে বলেছিলাম, ওরা একে অন্যের মাথা নিচু করে বসলো। দুটো খুঁজে বের করো।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏بَيْنَمَا أَنَا أُصَلِّي صَلَاةَ الظُّهْرِ سَلَّمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ رَكْعَتَيْنِ فَقَامَ ‏ ‏رَجُلٌ مِنْ ‏ ‏بَنِي سُلَيْمٍ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ أَقَصُرَتْ الصَّلَاةُ أَمْ نَسِيتَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ تَقْصُرْ وَلَمْ ‏ ‏أَنْسَهْ قَالَ يَا رَسُولَ اللَّهِ إِنَّمَا صَلَّيْتَ رَكْعَتَيْنِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحَقٌّ مَا يَقُولُ ‏ ‏ذُو الْيَدَيْنِ ‏ ‏قَالُوا نَعَمْ قَالَ فَقَامَ ‏ ‏فَصَلَّى بِهِمْ رَكْعَتَيْنِ آخِرَتَيْنِ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏حَدَّثَنِي ‏ ‏ضَمْضَمُ بْنُ جَوْسٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏ثُمَّ سَجَدَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَجْدَتَيْنِ ‏","","",""],[9100,9100,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি কার কাছে আত্মসমর্পণ করেছেন, সেই সম্বন্ধে তিনি বলেছিলেন । ( ১ করি.","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو سَلَمَةَ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ قَامَ رَمَضَانَ إِيمَانًا ‏ ‏وَاحْتِسَابًا ‏ ‏غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ وَمَنْ قَامَ لَيْلَةَ الْقَدْرِ إِيمَانًا ‏ ‏وَاحْتِسَابًا ‏ ‏غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏","","",""],[9101,9101,"","ঈশ্বর জানেন যে, আমি যে - প্রভুর বাক্য বলি, সেই ব্যক্তি এবং যে - পাপ করে, সেই সম্বন্ধে আমার বাবা কী বলেছিলেন । হে ঈশ্বর, এবং শাস্ত্রের মন্দ থেকে মৃত্যু।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏حَدَّثَنِي ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدْعُو بِهَؤُلَاءِ الْكَلِمَاتِ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ النَّارِ وَمِنْ عَذَابِ الْقَبْرِ وَمِنْ ‏ ‏فِتْنَةِ ‏ ‏الْمَحْيَا وَالْمَمَاتِ وَمِنْ شَرِّ ‏ ‏الْمَسِيحِ الدَّجَّالِ ‏","","",""],[9102,9102,"","আমরা সবাই এ কথা বলেছি যে তিনি আমাকে কখনও বলবেন না যে তিনি কখনও কোন আগুন শোনেন নি। ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং আত্মসমর্পণ করেছেন এবং প্রতারণার সাথে প্রতারণা না করার জন্য। যে নারী তাকে কখনও শেখানো হয় নি.","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو سَلَمَةَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُنْكَحُ الْمَرْأَةُ وَخَالَتُهَا وَلَا الْمَرْأَةُ وَعَمَّتُهَا ‏","","",""],[9103,9103,"","আমরা সবাই আমার বাবাকে খুশি করার কথা বলেছি যে সে তাকে বলেছিল আমি চাই। সে একজন দেবতা যে তার ইচ্ছা থেকে পালাতে পারবে না।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَحِلُّ لِامْرَأَةٍ أَنْ تُسَافِرَ يَوْمًا فَمَا فَوْقَهُ إِلَّا وَمَعَهَا ذُو حُرْمَةٍ ‏","","",""],[9104,9104,"","আমরা প্রভুর সংযুক্ত সেবার চমৎকার ব্যবস্থা করেছি, যা আমরা একটি স্বপ্নের কথা বলেছি... ...একটা রাজধানীর স্বপ্নের কথা যা আমি আগে কখনো করেছি, মৃত্যুর ফলে মৃত্যু পর্যন্ত আমি ভয় পাচ্ছি আগুন আত্মার প্রাণের আলো দেখতে পাবে। আমরা শত্রু বাবার মত নই, কিন্তু আমরা তা নই। আমার ভাই সম্বন্ধে কথা বলা যায় ।","‏ ‏حَدَّثَنَا ‏ ‏غَسَّانُ بْنُ الرَّبِيعِ مُوصِلِيٌّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ بَهْدَلَةَ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يُؤْتَى بِالْمَوْتِ كَبْشًا ‏ ‏أَغْثَرَ ‏ ‏فَيُوقَفُ بَيْنَ الْجَنَّةِ وَالنَّارِ فَيُقَالُ يَا أَهْلَ الْجَنَّةِ ‏ ‏فَيَشْرَئِبُّونَ ‏ ‏وَيَنْظُرُونَ وَيُقَالُ لِأَهْلِ النَّارِ فَيَشْرَئِبُّونَ وَيَنْظُرُونَ وَيَرَوْنَ أَنْ قَدْ جَاءَ الْفَرَجُ فَيُذْبَحُ فَيُقَالُ خُلُودٌ لَا مَوْتَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏وَمُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَاهُ ‏","","",""],[9105,9105,"","আমরা ঈশ্বরের ছেলের কথা বলেছিলাম আমরা আমার ছেলের দাস, কুমারী, ঈশ্বর তার কাছে প্রার্থনা করেন আর তিনি বলবেন না যে আমি আমার সর্বোচ্চ চেষ্টা করি আর আমার মা কখনো ঈশ্বর ও ঈশ্বর বলে কথা বলবে না। আমার মুখ আর রাজা বলবে, স্যার, আমি তাদের মালিক করব।","‏ ‏حَدَّثَنَا ‏ ‏غَسَّانُ بْنُ الرَّبِيعِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَقُولَنَّ أَحَدُكُمْ عَبْدِي وَأَمَتِي وَلَا يَقُولَنَّ الْمَمْلُوكُ رَبِّي وَرَبَّتِي لِيَقُلْ الْمَالِكُ فَتَايَ وَفَتَاتِي وَلْيَقُلْ الْمَمْلُوكُ سَيِّدِي وَسَيِّدَتِي فَإِنَّهُمْ الْمَمْلُوكُونَ وَالرَّبُّ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[9106,9106,"","আমরা বাবার স্বপ্নের কথা বলেছি ঈশ্বর তাকে জিজ্ঞেস করেছেন আর তিনি এমন কিছু বলতে চাচ্ছেন যেটা তিনি জেলে থাকার ভয় পেয়েছেন।","‏ ‏حَدَّثَنَا ‏ ‏غَسَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنْ كَانَ فِي شَيْءٍ مِمَّا ‏ ‏تَدَاوَوْنَ بِهِ خَيْرٌ فَفِي ‏ ‏الْحِجَامَةِ ‏","","",""],[9107,9107,"","আর সে লর্ডের প্রার্থনাকে ডাকতো, আর সে সারা রাত... ...আর বিষের মত ভালোবাসা দেবে।","‏ ‏وَبِإِسْنَادِهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْحَبَّةُ السَّوْدَاءُ شِفَاءٌ لِكُلِّ دَاءٍ إِلَّا السَّامَ وَالسَّامُ الْمَوْتُ ‏","","",""],[9108,9108,"","আর সে তাকে ভবিষ্যদ্বাণীর ব্যাপারে বলবে, তাকে উদ্ধার করতে হবে আর ছেলেটির ভালোর জন্য তাকে ভালো করতে হবে.","‏ ‏وَبِإِسْنَادِهِ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَنْ ‏ ‏يُونُسَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا سَمِعَ أَحَدُكُمْ الْأَذَانَ وَالْإِنَاءُ عَلَى يَدِهِ فَلَا يَدَعْهُ حَتَّى ‏ ‏يَقْضِيَ ‏ ‏مِنْهُ ‏","","",""],[9109,9109,"","আমি আনন্দিত যে আমার বাবা এটা প্রদান করার জন্য যে ভবিষ্যদ্বাণী করা হয়েছে, সে একজন জিনিয়াস। ঈশ্বর যদি বলেন, তারা আমাকে মেরে ফেলে এবং মারা যায়। ঈশ্বর আমার বাবাকে বলেছিলেন, তুমি তাদের খুন করবে বলেই ঈশ্বর বলে যে, আমি কুমারী এবং ঈশ্বর, আমি কোম্পানি এবং চিড়িয়াখানা ভেঙ্গে ফেলি না এবং যারা নিহত হয় তাদের হত্যা করি আমার সাথে ঝগড়া হয়ে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ حُسَيْنٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ابْنِ مَسْعُودٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أُمِرْتُ أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَقُولُوا لَا إِلَهَ إِلَّا اللَّهُ فَإِذَا قَالُوهَا ‏ ‏عَصَمُوا ‏ ‏مِنِّي دِمَاءَهُمْ وَأَمْوَالَهُمْ إِلَّا ‏ ‏بِحَقِّهَا ‏ ‏وَحِسَابُهُمْ عَلَى اللَّهِ عَزَّ وَجَلَّ ‏ ‏قَالَ ‏ ‏فَلَمَّا كَانَتْ الرِّدَّةُ ‏ ‏قَالَ ‏ ‏عُمَرُ ‏ ‏لِأَبِي بَكْرٍ ‏ ‏تُقَاتِلُهُمْ وَقَدْ سَمِعْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ كَذَا وَكَذَا قَالَ فَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَاللَّهِ لَا أُفَرِّقُ بَيْنَ الصَّلَاةِ وَالزَّكَاةِ وَلَأُقَاتِلَنَّ مَنْ فَرَّقَ بَيْنَهَا قَالَ فَقَاتَلْنَا مَعَهُ فَرَأَيْنَا ذَلِكَ رَشَدًا ‏","","",""],[9110,9110,"","সে বলেছিল তার বাবার সাথে কথা বলেছি আমরা তাকে জিজ্ঞেস করতে চাই। শয়তানের দল তাকে দেখবে.","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْحَمِيرِ فِيهَا زَكَاةٌ فَقَالَ مَا جَاءَنِي فِيهَا شَيْءٌ إِلَّا هَذِهِ الْآيَةُ ‏ ‏الْفَاذَّةُ ‏ { ‏مَنْ يَعْمَلْ ‏ ‏مِثْقَالَ ‏ ‏ذَرَّةٍ خَيْرًا يَرَهُ وَمَنْ يَعْمَلْ ‏ ‏مِثْقَالَ ‏ ‏ذَرَّةٍ شَرًّا يَرَهُ ‏}","","",""],[9111,9111,"","তিনি বলেছিলেন যে, আমার বাবা একজন নেতা হওয়ার জন্য দৃঢ়সংকল্পবদ্ধ ছিলেন । সে ভাড়া বা গান পেয়েছে।","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ مُحَمَّدُ بْنُ خَازِمٍ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَضَمَّنَ ‏ ‏اللَّهُ لِمَنْ يَخْرُجُ فِي سَبِيلِهِ أَنْ يُدْخِلَهُ الْجَنَّةَ أَوْ يَرُدَّهُ إِلَى مَنْزِلِهِ ‏ ‏نَائِلًا ‏ ‏مَا ‏ ‏نَالَ ‏ ‏مِنْ أَجْرٍ أَوْ غَنِيمَةٍ ‏","","",""],[9112,9112,"","আমি আমার বাবাকে বলেছিলাম যে, আমরা তার বাবার সঙ্গে বাস করছি । তোমার শপথের শপথ অনুযায়ী আমার পিতাকে ( দ্বিতীয় বিবরণ ৮: ১৪) আমি তোমার নামে শপথ করছি যে , তুমি আমার বাবার শপথের শপথকে মান ্ য কর । তুমি বলেছিলে যে , আমি তোমার নিকট শপথ করছি । তুমি আমার বাবার শপথের কথা বলেছ , তুমি বলেছিলে তোমার বাবার মত কাজ করবে । তুমি যদি আমার বাবার শপথের ব ্ যাপারে আমাকে বিরত থাকো , তবে আমি তোমার নিকট ফিরে আসতে পারব । আর আমি তোমার কাছে আমার বাবার শপথের শপথের কথা বলছি । নিশ ্ চয় আল ্ লাহ সর ্ ববিষয়ে সম ্ যক জ ্ ঞাত । বাপ্তাইজিত হয়ে এবং সে যেভাবে বলেছিল, সে তা বলেনি এবং সে বলেছে, সে একটা ছোট বাচ্চা।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْإِمَامُ ضَامِنٌ وَالْمُؤَذِّنُ مُؤْتَمَنٌ اللَّهُمَّ أَرْشِدْ الْأَئِمَّةَ وَاغْفِرْ لِلْمُؤَذِّنِينَ ‏ ‏قَالَ ‏ ‏وَكَذَا ‏ ‏حَدَّثَنَاهُ ‏ ‏أَسْوَدُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏كَمَا قَالَ ‏ ‏مُحَمَّدٌ ‏ ‏أَرْشِدْ الْأَئِمَّةَ وَاغْفِرْ لِلْمُؤَذِّنِينَ ‏ ‏قَالَ ‏ ‏وَكَذَا قَالَ ‏ ‏يَعْنِي ‏ ‏ابْنَ فُضَيْلٍ ‏ ‏أَيْضًا ‏ ‏وَزَائِدَةُ ‏ ‏أَيْضًا ‏ ‏حَدَّثَنَاهُ ‏ ‏مُعَاوِيَةُ ‏ ‏يَعْنِي ‏ ‏عَنْهُ ‏","","",""],[9113,9113,"","ঈশ্বর এবং কোরানে এক খোঁড়ার ব্যবস্থা করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِرَاءٌ ‏ ‏فِي الْقُرْآنِ كُفْرٌ ‏","","",""],[9114,9114,"","বাবা যখন মারা যান, তখন আমি আমার বাবাকে বলেছিলাম যে, তিনি একজন কুমারী । ভাড়া অথবা গান।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُهَيْلُ بْنُ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَضَمَّنَ ‏ ‏اللَّهُ لِمَنْ يَخْرُجُ فِي سَبِيلِهِ أَنْ يُدْخِلَهُ الْجَنَّةَ أَوْ يَرُدَّهُ إِلَى مَنْزِلِهِ ‏ ‏نَائِلًا ‏ ‏مَا ‏ ‏نَالَ ‏ ‏مِنْ أَجْرٍ أَوْ غَنِيمَةٍ ‏","","",""],[9115,9115,"","আমি আমার ভাইয়ের সঙ্গে ঝগড়া করাকে একজন উৎপীড়ক বলে বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَقَدْ هَمَمْتُ أَنْ لَا أَتَخَلَّفَ عَنْ ‏ ‏سَرِيَّةٍ ‏ ‏تَخْرُجُ فِي سَبِيلِ اللَّهِ وَلَيْسَ عِنْدِي مَا أَحْمِلُهُمْ وَلَوَدِدْتُ أَنِّي أُقْتَلُ فِي سَبِيلِ اللَّهِ ثُمَّ أَحْيَا ثُمَّ أُقْتَلُ ثُمَّ أَحْيَا ثُمَّ أُقْتَلُ ‏","","",""],[9116,9116,"","আমরা আমার বাবার কথা বলেছিলাম, লর্ডের কাছে গেরিলারা আছে... ...সে বলেছে তুমি তাকে কখনো উড়তে পারবে না। লর্ড মুক্ত না হওয়া পর্যন্ত ডার্ক লর্ডদের আমি কখনো নিরব হতে পারবো না।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُهَيْلٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالُوا يَا رَسُولَ اللَّهِ أَخْبِرْنَا بِعَمَلٍ يَعْدِلُ الْجِهَادَ فِي سَبِيلِ اللَّهِ قَالَ لَا تُطِيقُونَهُ مَرَّتَيْنِ ‏ ‏أَوْ ثَلَاثًا ‏ ‏قَالَ قَالُوا أَخْبِرْنَا فَلَعَلَّنَا نُطِيقُهُ قَالَ ‏ ‏مَثَلُ الْمُجَاهِدِ فِي سَبِيلِ اللَّهِ كَمَثَلِ الصَّائِمِ الْقَائِمِ ‏ ‏الْقَانِتِ ‏ ‏بِآيَاتِ اللَّهِ لَا ‏ ‏يَفْتُرُ ‏ ‏مِنْ صِيَامٍ وَلَا صَلَاةٍ حَتَّى يَرْجِعَ الْمُجَاهِدُ إِلَى أَهْلِهِ ‏","","",""],[9117,9117,"","আমরা আমার বাবার সাথে ঝগড়ার কথা বলেছিলাম যে সে নগ্ন ছিল। সে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عُذِّبَتْ امْرَأَةٌ فِي هِرَّةٍ رَبَطَتْهَا فَلَمْ تُطْعِمْهَا وَلَمْ تُرْسِلْهَا فَتَأْكُلَ مِنْ حَشَرَاتِ الْأَرْضِ ‏","","",""],[9118,9118,"","আমরা আমার বাবার সাথে পলাতক হিসেবে যুদ্ধ করেছি, যে বলেছে সে সুখী হতে যাচ্ছে। তাদের তা করতে হবে। আমি নিশ্চিত, ঈশ্বরের ইচ্ছা তাকে ব্যর্থ করতে এবং বলে সে তোমাকে মেরে ফেলবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي رَزِينٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُهُ يَضْرِبُ جَبْهَتَهُ بِيَدِهِ وَيَقُولُ يَا أَهْلَ ‏ ‏الْعِرَاقِ ‏ ‏تَزْعُمُونَ أَنِّي أَكْذِبُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِيَكُنْ ‏ ‏لَكُمُ ‏ ‏الْمَهْنَأُ وَعَلَيَّ الْإِثْمُ أَشْهَدُ لَسَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا انْقَطَعَ ‏ ‏شِسْعُ ‏ ‏أَحَدِكُمْ فَلَا يَمْشِي فِي الْأُخْرَى حَتَّى يُصْلِحَهَا ‏","","",""],[9119,9119,"","আর তারপর কুকুরদের বলতে হবে যে একবার তারা পরিষ্কার হয়ে যাবে।","‏ ‏وَإِذَا ‏ ‏وَلَغَ ‏ ‏الْكَلْبُ فِي إِنَاءِ أَحَدِكُمْ فَلَا يَتَوَضَّأْ حَتَّى يَغْسِلَهَا سَبْعَ مَرَّاتٍ ‏","","",""],[9120,9120,"","আমার বাবার সাথে ঝগড়ার কথা বলেছিলাম সে আমাকে বলেছে সে আমাকে ছেড়ে দিবে, সে আলো বন্ধ করে দিবে আর সে ভালো থাকবে আর সে ক্লান্ত হয়ে যাবে আর আমরা ঠিক হয়ে যাব। তিন দিন পর তিনি বলেছিলেন যে, কে ক্ষতটা স্পর্শ করতে পারে গায়াকে হারাতে পারে ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ تَوَضَّأَ يَوْمَ الْجُمُعَةِ فَأَحْسَنَ الْوُضُوءَ ثُمَّ أَتَى الْجُمُعَةَ فَدَنَا وَأَنْصَتَ وَاسْتَمَعَ غُفِرَ لَهُ مَا بَيْنَهُ وَبَيْنَ الْجُمُعَةِ وَزِيَادَةُ ثَلَاثَةِ أَيَّامٍ قَالَ وَمَنْ مَسَّ الْحَصَى فَقَدْ ‏ ‏لَغَا ‏","","",""],[9121,9121,"","আমি যদি আমার ইচ্ছা মেনে নেওয়ার জন্য আমাকে হুমকি দিই, তা হলে আমি তা মেনে নিতে বাধ্য হব । আমার ভয়, আতঙ্ক।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏وَوَكِيعٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ أُهْدِيَتْ لِي ذِرَاعٌ لَقَبِلْتُ وَلَوْ دُعِيتُ إِلَى ‏ ‏كُرَاعٍ ‏ ‏لَأَجَبْتُ ‏ ‏قَالَ ‏ ‏وَكِيعٌ ‏ ‏فِي حَدِيثِهِ لَوْ أُهْدِيَتْ إِلَيَّ ذِرَاعٌ ‏","","",""],[9122,9122,"","বাবা আমরা বাবাকে বলেছিলাম যে, আমার বাবাকে জানার কথা, একজন পলাতক তার কাছে প্রার্থনা করেন আর আমি বিশ্বাস করব টাক হাতে প্রার্থনা করা টাক আছে. তারা জানে তারা আসলে কি নয়. কিন্তু বলার জন্য, একজন মানুষ... ...তাদের প্রার্থনা করার জন্য ভীত.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏وَابْنُ نُمَيْرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْأَعْمَشُ ‏ ‏الْمَعْنَى ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَثْقَلُ الصَّلَاةِ عَلَى الْمُنَافِقِينَ صَلَاةُ الْعِشَاءِ وَصَلَاةُ الْفَجْرِ وَلَوْ يَعْلَمُونَ مَا فِيهِمَا لَأَتَوْهُمَا وَلَوْ ‏ ‏حَبْوًا ‏ ‏وَلَقَدْ هَمَمْتُ أَنْ آمُرَ الْمُؤَذِّنَ فَيُؤَذِّنَ ثُمَّ آمُرَ رَجُلًا ‏ ‏يُصَلِّي بِالنَّاسِ ثُمَّ أَنْطَلِقَ مَعِي بِرِجَالٍ مَعَهُمْ حُزُمُ الْحَطَبِ إِلَى قَوْمٍ يَتَخَلَّفُونَ عَنْ الصَّلَاةِ فَأُحَرِّقَ عَلَيْهِمْ بُيُوتَهُمْ بِالنَّارِ ‏","","",""],[9123,9123,"","ঈশ্বরের কাছে প্রার্থনা করার সময় তিনি বলেছিলেন যে, তাকে কোন ছায়া বা ছায়াতে কখনও হস্তান্তর করা হবে না । জীবাশ্ম।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏وَابْنُ نُمَيْرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي الْحَكَمِ ‏ ‏مَوْلَى ‏ ‏اللَّيْثِيِّينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏سَبَقَ ‏ ‏إِلَّا فِي ‏ ‏خُفٍّ ‏ ‏أَوْ ‏ ‏حَافِرٍ ‏","","",""],[9124,9124,"","দুই বছর আগে আমার বাবার সাথে ঝগড়ার কথা বলেছিলাম, সে আমাকে ছেড়ে চলে যেতে বলেছে, সে আমাকে ঘুমের মধ্যে দেখে নিতো।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ رَآنِي فِي الْمَنَامِ فَقَدْ رَآنِي الْحَقَّ إِنَّ الشَّيْطَانَ لَا يَسْتَطِيعُ أَنْ يَتَشَبَّهَ بِي ‏","","",""],[9125,9125,"","আমি যখন তাকে অভিশাপ দেই, তখন ঈশ্বর তাকে রক্ষা করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ وَهُوَ ابْنُ عُلَيَّةَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ حَسَّانَ ‏ ‏وَيَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ نَسِيَ وَهُوَ صَائِمٌ فَأَكَلَ أَوْ شَرِبَ فَلْيُتِمَّ صَوْمَهُ فَإِنَّمَا أَطْعَمَهُ اللَّهُ وَسَقَاهُ ‏","","",""],[9126,9126,"","আমরা একটি মেয়ে বা বাবার একটি বিড়ালের সাথে দেখা করার চেষ্টা করার কথা বলেছিলাম। প্রার্থনা আগুনের শিখাতে এবং আগুনে পুড়ে যায় এবং মহিলা বলে যে আমি তাকে কোন শপথ করি না যে প্রভু হচ্ছেন প্রভু। আমি জানি, আমি জানি না, আমি কি করছি।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامٌ الدَّسْتُوَائِيُّ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏زُرَارَةَ بْنِ أَوْفَى ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏يَقْطَعُ الصَّلَاةَ الْكَلْبُ وَالْحِمَارُ وَالْمَرْأَةُ قَالَ ‏ ‏هِشَامٌ ‏ ‏وَلَا أَعْلَمُهُ إِلَّا عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[9127,9127,"","আমরা বাবাকে বলেছিলাম আমি আমার বাবাকে কতটা ভালোবাসি। সে বলল, ঈশ্বর তার জন্য প্রার্থনা করুক। আর সে তার আত্মা দিয়ে যে জামাটি বয়ে আনবে, তা সে তার প্রাণে পৌঁছে দেবে। আর সে মনে করে যে সে বলবে সে চুপ থাকবে। তাই সে তাকে বলল, আমি আমার বাবাকে অনেক ভালোবাসি। তাই আমি আমার বাবার কাছে এটা একটা গোপন রাখতে চাই। আর আমি জানি না যে আমি জানি না, আমি জানি না, আমি যদি আমি এটা করি, আমি আমার বাবা আমাকে এটা করতে চাই। আমি জানি যে আমি জানি না। আমি জানি না। আমি যদি আমার বাবা আমাকে এটা করতে চাই, আমি শুধু একটা কথা বলি, আমি জানি না। আমি জানি, আমি জানি যে, আমি জানি না। আমি জানি, আমি জানি না যে, আমি জানি, আমি যদি আমার বাবা আমাকে এটা একটা কাজ করতে হবে। আর আমি জানি না। আমি জানি না। আমি জানি, আমি যদি আমার বাবা আমাকে এটা করতে হবে। আমি তাকে জিজ্ঞেস করি, আমি জানি যে, আমি জানি যে, আমি জানি, আমি জানি যে, আমি জানি, আমি আমার বাবা আমাকে জিজ্ঞেস করে, আপ.","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْحَجَّاجُ بْنُ أَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الثَّيِّبُ ‏ ‏تُسْتَأْمَرُ ‏ ‏فِي نَفْسِهَا وَالْبِكْرُ تُسْتَأْذَنُ قَالُوا يَا رَسُولَ اللَّهِ وَكَيْفَ إِذْنُهَا قَالَ أَنْ تَسْكُتَ ‏","","",""],[9128,9128,"","আমার বাবা একজন পলাতক ছিলেন, যিনি ঈশ্বরের কাছে প্রার্থনা করেছিলেন যে তিনি তার প্রস্তাব বা আমার কাছে সমর্পণ করেছেন তার প্রতারণার তিন বছর পর তিন বছর ধরে মিথ্যা গুজব ছড়িয়ে পড়ে যে, তিন বছর হয় স্বর্গে প্রবেশ করে, সাক্ষী এবং দেবীর মন্দির। এক হিংস্র হামলা যা আগে মারা গিয়েছিল বা তিন বার। যে আগুন দিয়ে যেতে হবে, সে এক বিস্ময়কর রাজপুত্র।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ الدَّسْتُوَائِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَامِرٍ الْعُقَيْلِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عُرِضَ عَلَيَّ أَوَّلُ ثَلَاثَةٍ يَدْخُلُونَ الْجَنَّةَ وَأَوَّلُ ثَلَاثَةٍ يَدْخُلُونَ النَّارَ فَأَمَّا أَوَّلُ ثَلَاثَةٍ يَدْخُلُونَ الْجَنَّةَ فَالشَّهِيدُ وَعَبْدٌ مَمْلُوكٌ أَحْسَنَ عِبَادَةَ رَبِّهِ وَنَصَحَ لِسَيِّدِهِ وَعَفِيفٌ ‏ ‏مُتَعَفِّفٌ ‏ ‏ذُو عِيَالٍ وَأَمَّا أَوَّلُ ثَلَاثَةٍ يَدْخُلُونَ النَّارَ فَأَمِيرٌ مُسَلَّطٌ وَذُو ثَرْوَةٍ مِنْ مَالٍ لَا يُعْطِي حَقَّ مَالِهِ وَفَقِيرٌ فَخُورٌ ‏","","",""],[9129,9129,"","আমি আমার বাবাকে আমার ভালবাসা সম্বন্ধে অনেক কিছু বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامٌ الدَّسْتُوَائِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَمْسَكَ كَلْبًا فَإِنَّهُ يُنْقِصُ مِنْ عَمَلِهِ كُلَّ يَوْمٍ ‏ ‏قِيرَاطًا ‏ ‏إِلَّا كَلْبَ ‏ ‏حَرْثٍ ‏ ‏أَوْ مَاشِيَةٍ ‏","","",""],[9130,9130,"","আমি বলেছিলাম যে, একজন উপপত্নীর ছেলে, আমি একজন মা ছাড়া অন্য কোনো ঘোড়া অথবা ঘোড়ার ছেলে । ঈশ্বর আপনার প্রতি আপনাকে করুণা দেখান, প্রথমে লোকেদের গণনা করা হল সেই দিন । কিছু একটা আমাকে বলে, তারা আমাকে বঁড়শি থেকে বিরত থাকতে বলেছিল, তারপর ভয় পেতে হবে। সে বলল, \"লন্স\" আর আমি এটা নিয়ে আসব।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يُونُسُ يَعْنِي ابْنَ عُبَيْدٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ حَكِيمٍ الضَّبِّيِّ ‏ ‏أَنَّهُ خَافَ زَمَنَ ‏ ‏زِيَادٍ ‏ ‏أَوْ ‏ ‏ابْنِ زِيَادٍ ‏ ‏فَأَتَى ‏ ‏الْمَدِينَةَ ‏ ‏فَلَقِيَ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏فَانْتَسَبَنِي فَانْتَسَبْتُ لَهُ فَقَالَ يَا فَتَى أَلَا أُحَدِّثُكَ حَدِيثًا لَعَلَّ اللَّهَ أَنْ يَنْفَعَكَ بِهِ قُلْتُ بَلَى رَحِمَكَ اللَّهُ قَالَ ‏ ‏إِنَّ أَوَّلَ مَا يُحَاسَبُ بِهِ النَّاسُ يَوْمَ الْقِيَامَةِ مِنْ الصَّلَاةِ قَالَ يَقُولُ رَبُّنَا عَزَّ وَجَلَّ لِمَلَائِكَتِهِ وَهُوَ أَعْلَمُ انْظُرُوا فِي صَلَاةِ عَبْدِي أَتَمَّهَا أَمْ نَقَصَهَا فَإِنْ كَانَتْ تَامَّةً كُتِبَتْ لَهُ تَامَّةً وَإِنْ كَانَ انْتَقَصَ مِنْهَا شَيْئًا قَالَ انْظُرُوا هَلْ لِعَبْدِي مِنْ تَطَوُّعٍ فَإِنْ كَانَ لَهُ تَطَوُّعٌ قَالَ أَتِمُّوا لِعَبْدِي فَرِيضَتَهُ مِنْ تَطَوُّعِهِ ثُمَّ تُؤْخَذُ الْأَعْمَالُ عَلَى ذَلِكُمْ قَالَ ‏ ‏يُونُسُ ‏ ‏وَأَحْسَبُهُ قَدْ ذَكَرَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[9131,9131,"","আমরা আমার বাবাকে ঈশ্বরের কাছে নিয়ে যাবার কথা বলেছিলাম, তাকে তার প্রার্থনা করার আগে তার কাছে যা বিশ্বাস করা উচিত, তা সমর্পণ করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا يَأْمَنُ الَّذِي يَرْفَعُ رَأْسَهُ فِي صَلَاتِهِ قَبْلَ الْإِمَامِ أَنْ يُحَوِّلَ اللَّهُ صُورَتَهُ صُورَةَ حِمَارٍ ‏","","",""],[9132,9132,"","আমি আমার বাবাকে নগ্ন অবস্থায় খুঁজে পাওয়ার চেষ্টা করার বিষয়ে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنِ ‏ ‏الْحَجَّاجِ بْنِ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ إِسْمَاعِيلَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَيَعْجِزُ أَحَدُكُمْ إِذَا صَلَّى أَنْ يَتَقَدَّمَ أَوْ يَتَأَخَّرَ أَوْ عَنْ يَمِينِهِ أَوْ عَنْ شِمَالِهِ ‏","","",""],[9133,9133,"","আমরা আমার বাবার কথা বলেছিলাম কেন তিনি তাকে বলতে বলেছেন তিনি আপনার শান্তি আসবে এবং আপনার আনন্দ, ঈশ্বর তাঁর কৃতকর্মের উপর আশীর্বাদ করুন, এবং তাঁর কাজ অবিশ্বাস্য. সে তার সেরাদের মাসের এক মাসেরও বেশি সময় ধরে এটা করে আসছে।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏لَمَّا حَضَرَ رَمَضَانُ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ جَاءَكُمْ رَمَضَانُ شَهْرٌ مُبَارَكٌ افْتَرَضَ اللَّهُ عَلَيْكُمْ صِيَامَهُ تُفْتَحُ فِيهِ أَبْوَابُ الْجَنَّةِ وَتُغْلَقُ فِيهِ أَبْوَابُ الْجَحِيمِ ‏ ‏وَتُغَلُّ ‏ ‏فِيهِ الشَّيَاطِينُ فِيهِ لَيْلَةٌ خَيْرٌ مِنْ أَلْفِ شَهْرٍ مَنْ حُرِمَ خَيْرَهَا فَقَدْ حُرِمَ ‏","","",""],[9134,9134,"","আমরা বাবার বন্য দেবীর জন্য আমাদের সাহায্যের কথা বলেছি, তিনি বলেছিলেন ঈশ্বর বিজয় পেয়েছেন এবং তার সাথে কথা বলার জন্য আমার মা জিতেছে।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏زُرَارَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ ‏ ‏تَجَاوَزَ ‏ ‏لِأُمَّتِي عَمَّا حَدَّثَتْ بِهِ أَنْفُسَهَا مَا لَمْ تَكَلَّمْ بِهِ ‏","","",""],[9135,9135,"","আমরা আমার বাবা আমাদের বলতে চাই কিভাবে ঈশ্বরকে বলতে হয়, তিনি শান্তি পাবেন আর আমরা তার হাত ধরে চিন্তা করব যে ভিলেনরা প্রান্তরে যাচ্ছে.","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي مُصْعَبٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنَحَا بِيَدِهِ نَحْوَ ‏ ‏الْيَمَنِ ‏ ‏الْإِيمَانُ يَمَانٍ الْإِيمَانُ يَمَانٍ الْإِيمَانُ يَمَانٍ رَأْسُ الْكُفْرِ الْمَشْرِقُ وَالْكِبْرُ وَالْفَخْرُ فِي ‏ ‏الْفَدَّادِينَ ‏ ‏أَصْحَابِ ‏ ‏الْوَبَرِ ‏","","",""],[9136,9136,"","আমরা আমার ছেলের হাই স্কুলের কথা বলেছিলাম আমরা আমার বাবার ঋণের কথা ফিরে পেয়েছি, ঈশ্বরের এটা করতে হবে আর তার ভাইয়ের ভাইয়ের কাছে সে পৌঁছে দিবে। যুবকদের দিকে নয়.","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ابْنُ عُلَيَّةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ أَبِي هِنْدٍ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ تُنْكَحَ الْمَرْأَةُ عَلَى عَمَّتِهَا وَالْعَمَّةُ عَلَى بِنْتِ أَخِيهَا وَالْمَرْأَةُ عَلَى خَالَتِهَا وَالْخَالَةُ عَلَى بِنْتِ أُخْتِهَا لَا تُنْكَحُ الْكُبْرَى عَلَى الصُّغْرَى وَلَا الصُّغْرَى عَلَى الْكُبْرَى ‏","","",""],[9137,9137,"","ঈশ্বর আদেশ দিয়েছেন, যে সমস্ত লোকের হত্যা করেছে, প্রভু তাদের প্রতি সমর্পণ করবেন, প্রভু নন কে বলেছে তার আনুগত্য আর তার বই আর তার নির্দেশনা নিশ্চিত হবে যে অন্য আরেকজনের কথা ঘটবে। পরাজয়ের সাজে নিশ্চয়ই প্রভুর আদেশ হতে হবে। তুমি তাকে দেখতে পাচ্ছ না। সে তোমাকে বলবে, ঈশ্বর একদিন বলছেন, সে হচ্ছে সেই দিন যে সে বসে আছে। আমি আপনাকে তার জড়িত কথা বলবো যদি জাতি তার আত্মার দুর্ভাগ্যের জন্য থাকে। তারপর তুমি প্রভুর কাছে প্রার্থনা করো। যদি ঈশ্বর তার জন্য প্রার্থনা করে থাকেন, তিনি তা করবেন। যদি সে এক ঘন্টার বিজ্ঞানে আছে, আমি তোমাকে আগামীকাল যা পেতে চাই, তাহলে তুমি তার দিকে ঘুরিয়ে দিবে... ...আর তুমি কি করবে তার উপর. লোকেরা তাদের ধর্মকে শিক্ষা দেয় ।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو حَيَّانَ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ بْنِ عَمْرِو بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمًا بَارِزًا لِلنَّاسِ فَأَتَاهُ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ مَا الْإِيمَانُ قَالَ ‏ ‏الْإِيمَانُ أَنْ تُؤْمِنَ بِاللَّهِ وَمَلَائِكَتِهِ وَكِتَابِهِ وَلِقَائِهِ وَرُسُلِهِ وَتُؤْمِنَ بِالْبَعْثِ الْآخِرِ قَالَ يَا رَسُولَ اللَّهِ مَا الْإِسْلَامُ قَالَ الْإِسْلَامُ أَنْ تَعْبُدَ اللَّهَ لَا تُشْرِكُ بِهِ شَيْئًا وَتُقِيمَ الصَّلَاةَ الْمَكْتُوبَةَ وَتُؤْتِيَ الزَّكَاةَ الْمَفْرُوضَةَ وَتَصُومَ رَمَضَانَ قَالَ يَا رَسُولَ اللَّهِ مَا الْإِحْسَانُ قَالَ أَنْ تَعْبُدَ اللَّهَ كَأَنَّكَ تَرَاهُ فَإِنَّكَ إِنْ لَا تَرَاهُ فَإِنَّهُ يَرَاكَ فَقَالَ يَا رَسُولَ اللَّهِ مَتَى السَّاعَةُ قَالَ مَا الْمَسْئُولُ عَنْهَا بِأَعْلَمَ مِنْ السَّائِلِ وَلَكِنْ سَأُحَدِّثُكَ عَنْ ‏ ‏أَشْرَاطِهَا ‏ ‏إِذَا وَلَدَتْ الْأَمَةُ ‏ ‏رَبَّهَا ‏ ‏فَذَاكَ مِنْ ‏ ‏أَشْرَاطِهَا ‏ ‏وَإِذَا كَانَتْ الْعُرَاةُ الْحُفَاةُ الْجُفَاةُ رُءُوسَ النَّاسِ فَذَاكَ مِنْ ‏ ‏أَشْرَاطِهَا ‏ ‏وَإِذَا ‏ ‏تَطَاوَلَ ‏ ‏رُعَاةُ ‏ ‏الْبَهْمِ ‏ ‏فِي الْبُنْيَانِ فَذَلِكَ مِنْ ‏ ‏أَشْرَاطِهَا ‏ ‏فِي خَمْسٍ لَا يَعْلَمُهُنَّ إِلَّا اللَّهُ ثُمَّ تَلَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَذِهِ الْآيَةَ ‏ { ‏إِنَّ اللَّهَ عِنْدَهُ عِلْمُ السَّاعَةِ وَيُنَزِّلُ ‏ ‏الْغَيْثَ ‏ ‏وَيَعْلَمُ مَا فِي الْأَرْحَامِ وَمَا تَدْرِي نَفْسٌ مَاذَا تَكْسِبُ غَدًا وَمَا تَدْرِي نَفْسٌ بِأَيِّ أَرْضٍ تَمُوتُ إِنَّ اللَّهَ عَلِيمٌ خَبِيرٌ ‏} ‏ثُمَّ ‏ ‏أَدْبَرَ ‏ ‏الرَّجُلُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رُدُّوا عَلَيَّ الرَّجُلَ فَأَخَذُوا لِيَرُدُّوهُ فَلَمْ يَرَوْا شَيْئًا فَقَالَ هَذَا ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏جَاءَ لِيُعَلِّمَ النَّاسَ دِينَهُمْ ‏","","",""],[9138,9138,"","আমরা আমার এক সুখী সন্তান থাকার কথা বলেছি, একটা ভবিষ্যদ্বাণীর জন্য তার কাছে প্রার্থনা করেছে আর সে তার জীবনে আমি সবচেয়ে বেশি ভালোবাসি, যদি তার কাছে কোন অর্থ নেই, সে খুশি হবে। খেল।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏النَّضْرِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏بَشِيرِ بْنِ نَهِيكٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَعْتَقَ ‏ ‏شِقْصًا ‏ ‏لَهُ فِي عَبْدٍ ‏ ‏فَخَلَاصُهُ ‏ ‏فِي مَالِهِ إِنْ كَانَ لَهُ مَالٌ فَإِنْ لَمْ يَكُنْ لَهُ مَالٌ اسْتُسْعِيَ الْعَبْدُ غَيْرَ مَشْقُوقٍ عَلَيْهِ ‏","","",""],[9139,9139,"","ঈশ্বর তাকে আদেশ দিয়েছেন এবং তিনি যে - শপথ করেছিলেন, তা যখন উল্লেখ করেছিলেন, তখন তিনি আত্মসমর্পণ করবেন, তখন তিনি তা করবেন । তার সবচেয়ে ভালো আর তারপর তিনি বলেছেন যে তিনি তার জীবন ধ্বংস করতে পারবেন না। এর মূল্য হচ্ছে, ঈশ্বর, আমি ক্ষমা করে দিচ্ছি, আমি তোমার জন্য ঠিক আছি। ঈশ্বরের দয়া করে বলতে হবে যে তার কাছে ঈশ্বরের দয়া আছে, আমি তোমাকে বলতে চাই না আমি এটা জিততে পারব। আশা করি, আমি তোমাকে স্যামের সাথে দেখা করতে ব্যর্থ হতে পারি, আশা করি তোমার কাছে কিছু আছে, আমি তোমাকে একটা জিনিস দিয়ে দেই।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو حَيَّانَ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ بْنِ عَمْرِو بْنِ جَرِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَامَ فِينَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمًا فَذَكَرَ ‏ ‏الْغُلُولَ ‏ ‏فَعَظَّمَهُ وَعَظَّمَ أَمْرَهُ ثُمَّ قَالَ ‏ ‏لَا أُلْفِيَنَّ يَجِيءُ أَحَدُكُمْ يَوْمَ الْقِيَامَةِ عَلَى رَقَبَتِهِ بَعِيرٌ لَهُ ‏ ‏رُغَاءٌ ‏ ‏فَيَقُولُ يَا رَسُولَ اللَّهِ أَغِثْنِي فَأَقُولُ لَا أَمْلِكُ لَكَ شَيْئًا قَدْ أَبْلَغْتُكَ لَا أُلْفِيَنَّ يَجِيءُ أَحَدُكُمْ يَوْمَ الْقِيَامَةِ عَلَى رَقَبَتِهِ شَاةٌ لَهَا ‏ ‏ثُغَاءٌ ‏ ‏فَيَقُولُ يَا رَسُولَ اللَّهِ أَغِثْنِي فَأَقُولُ لَا أَمْلِكُ لَكَ شَيْئًا قَدْ أَبْلَغْتُكَ لَا أُلْفِيَنَّ أَحَدَكُمْ يَجِيءُ يَوْمَ الْقِيَامَةِ عَلَى رَقَبَتِهِ فَرَسٌ لَهُ ‏ ‏حَمْحَمَةٌ ‏ ‏فَيَقُولُ يَا رَسُولَ اللَّهِ أَغِثْنِي فَأَقُولُ لَا أَمْلِكُ لَكَ شَيْئًا قَدْ أَبْلَغْتُكَ لَا أُلْفِيَنَّ يَجِيءُ أَحَدُكُمْ يَوْمَ الْقِيَامَةِ عَلَى رَقَبَتِهِ نَفْسٌ لَهَا صِيَاحٌ فَيَقُولُ يَا رَسُولَ اللَّهِ أَغِثْنِي فَأَقُولُ لَا أَمْلِكُ لَكَ شَيْئًا قَدْ أَبْلَغْتُكَ لَا أُلْفِيَنَّ يَجِيءُ أَحَدُكُمْ يَوْمَ الْقِيَامَةِ عَلَى رَقَبَتِهِ ‏ ‏رِقَاعٌ ‏ ‏تَخْفِقُ ‏ ‏فَيَقُولُ يَا رَسُولَ اللَّهِ أَغِثْنِي فَأَقُولُ لَا أَمْلِكُ لَكَ شَيْئًا قَدْ أَبْلَغْتُكَ لَا أُلْفِيَنَّ يَجِيءُ أَحَدُكُمْ يَوْمَ الْقِيَامَةِ عَلَى رَقَبَتِهِ ‏ ‏صَامِتٌ ‏ ‏فَيَقُولُ يَا رَسُولَ اللَّهِ أَغِثْنِي فَأَقُولُ لَا أَمْلِكُ لَكَ شَيْئًا قَدْ أَبْلَغْتُكَ ‏","","",""],[9140,9140,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং আমি আমার সমস্ত সংবাদকে আমার সকলের কাছে বলার জন্য আত্মসমর্পণ করব । আমার মা একজন ঐশিক জিনিস যে কখনো তোমাকে কিছু বলে নি যা আবেগে ভরে যায়।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏وَيَعْلَى بْنُ عُبَيْدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ لِكُلِّ نَبِيٍّ دَعْوَةً مُسْتَجَابَةً فَتَعَجَّلَ كُلُّ نَبِيٍّ دَعْوَتَهُ وَإِنِّي اخْتَبَأْتُ دَعْوَتِي ‏ ‏شَفَاعَةً ‏ ‏لِأُمَّتِي فَهِيَ ‏ ‏نَائِلَةٌ ‏ ‏إِنْ شَاءَ اللَّهُ مَنْ مَاتَ لَا يُشْرِكُ بِاللَّهِ شَيْئًا ‏ ‏قَالَ ‏ ‏يَعْلَى ‏ ‏الشَّفَاعَةُ ‏","","",""],[9141,9141,"","আমরা বাবার সঙ্গে এমন ব্যবহার করেছিলাম, যেন আমরা তার বাবা - মায়ের সঙ্গে কথা বলেছিলাম । আমার বাবার নাম হল তার ছেলের জন্য দেবতা.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثَلُ الصَّلَوَاتِ الْخَمْسِ كَمَثَلِ نَهْرٍ جَارٍ غَمْرٍ عَلَى بَابِ أَحَدِكُمْ يَغْتَسِلُ مِنْهُ كُلَّ يَوْمٍ خَمْسَ مَرَّاتٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَبْدِ اللَّهِ بْنِ أُسَامَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ فَمَاذَا يُبْقِي ذَلِكَ مِنْ الدَّرَنِ ‏","","",""],[9142,9142,"","আমি দেখেছি যে, তিনি যে - খাবারগুলো অর্জন করেছেন, সেগুলো তিনি নিজে নিজে করেছেন এবং যে - খাবার তিনি করেছেন, সেগুলো বিতরণ করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي يَحْيَى ‏ ‏مَوْلَى ‏ ‏جَعْدَةَ بْنِ هُبَيْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏مَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَابَ طَعَامًا قَطُّ كَانَ إِذَا اشْتَهَاهُ أَكَلَهُ وَإِنْ لَمْ يَشْتَهِهِ سَكَتَ ‏","","",""],[9143,9143,"","আমরা আমার ভাই হার্বারকে জিজ্ঞেস করতে চেষ্টা করার ব্যাপারে কথা বলেছিলাম। সে বলবে আল্লাহ আমার মহান নেতাদের প্রতি দয়া আর আনন্দের জন্য। আমার দেখা.","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏عَطَاءُ بْنُ السَّائِبِ ‏ ‏عَنِ ‏ ‏الْأَغَرِّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏الْكِبْرِيَاءُ رِدَائِي وَالْعَظَمَةُ ‏ ‏إِزَارِي ‏ ‏فَمَنْ يُنَازِعُنِي وَاحِدَةً مِنْهُمَا أَلْقَيْتُهُ فِي جَهَنَّمَ ‏","","",""],[9144,9144,"","আমরা আমার ভাইয়ের ভাঙ্গা অবস্থা নিয়ে কথা বলেছি কিন্তু একজন বেপটিস্ট ছেলে তার জন্মের আগে তোমাকে উদ্ধার করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ حَسَّانَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ تَابَ قَبْلَ أَنْ تَطْلُعَ الشَّمْسُ مِنْ مَغْرِبِهَا تَابَ اللَّهُ عَلَيْهِ ‏","","",""],[9145,9145,"","আমরা এমন একটা ছেলের কথা বলেছিলাম, যিনি এক ভাল শট নিয়ে কাজ করছেন ।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنِ ‏ ‏ابْنِ عَوْنٍ ‏ ‏عَنْ ‏ ‏عُمَيْرِ بْنِ إِسْحَاقَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏لَقِيَ ‏ ‏الْحَسَنَ ‏ ‏فَقَالَ لَهُ اكْشِفْ عَنْ بَطْنِكَ حَتَّى أُقَبِّلَ حَيْثُ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُقَبِّلُ مِنْهُ قَالَ فَكَشَفَ عَنْ بَطْنِهِ فَقَبَّلَهُ ‏","","",""],[9146,9146,"","আমরা আমার বাবার চেয়ে ভালো ক্যারিয়ারের কথা বলেছিলাম, সে বলে সে এটা ছেড়ে দিবে।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ حَسَّانَ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏طُهُورُ إِنَاءِ أَحَدِكُمْ إِذَا ‏ ‏وَلَغَ ‏ ‏فِيهِ الْكَلْبُ أَنْ يَغْسِلَهُ سَبْعَ مَرَّاتٍ أُولَاهُنَّ بِالتُّرَابِ ‏","","",""],[9147,9147,"","বাবার মৃত্যুর কথা বলেছিলাম, সে ঈশ্বরের কাছে প্রার্থনা করে... ...যদি তোমাকে একদিনে রাখতে হয়।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ الدَّسْتُوَائِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا صَلَّى أَحَدُكُمْ فِي ثَوْبٍ وَاحِدٍ فَلْيُخَالِفْ مَا بَيْنَ طَرَفَيْهِ عَلَى ‏ ‏عَاتِقَيْهِ ‏","","",""],[9148,9148,"","আমরা অনেক কথা বলেছি, একটি ভালো ছেলে সম্পর্কে আমাদের অনেক কথা বলেছি। তিনি বলেছিলেন, ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং তার সব সাহায্য দিয়েছেন এবং তিনি একটি নাম সাহায্য করেছেন। জঘন্য।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏وَيَزِيدُ يَعْنِي ابْنَ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلَّهِ عَزَّ وَجَلَّ تِسْعَةٌ وَتِسْعُونَ اسْمًا مِائَةٌ إِلَّا وَاحِدًا مَنْ ‏ ‏أَحْصَاهَا ‏ ‏كُلَّهَا دَخَلَ الْجَنَّةَ ‏","","",""],[9149,9149,"","আমার ভাই হার্লে আমাদের কথা বলেছে তার প্রিয় বন্ধুর ব্যাপারে। আমি প্রার্থনা করতে পারি, আমি তাকে সাহায্য করব, আমি তাকে সাহায্য করব, আমি যা করব এবং করব তা করব।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏ثُوِّبَ ‏ ‏بِالصَّلَاةِ فَلَا ‏ ‏يَسْعَى ‏ ‏إِلَيْهَا أَحَدُكُمْ وَلَكِنْ لِيَمْشِ وَعَلَيْهِ ‏ ‏السَّكِينَةُ ‏ ‏وَالْوَقَارُ صَلِّ مَا أَدْرَكْتَ وَاقْضِ مَا سَبَقَكَ ‏","","",""],[9150,9150,"","ঈশ্বর আমাকে উদ্ধার করেছেন, আপনি অগ্নির মতো অন্ত্যেষ্টিক্রিয়ার পথ অনুসরণ করবেন না এবং আমরা চুপ থাকব না ।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏هِشَامٍ الدَّسْتُوَائِيِّ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُتْبَعُ الْجِنَازَةُ بِنَارٍ وَلَا صَوْتٍ ‏","","",""],[9151,9151,"","আমরা আমার বাবার জন্মের কথা ভুলে গেছি। সে বলেছিল, প্রান্তরে আমাদের ছেলে একটা কথাওও পায়নি, সে শয়তানকে মারতে যাচ্ছে। আর ঈশ্বর আছে। একটা কথা বলো।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَجُلًا جَاءَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّ فُلَانًا نَامَ الْبَارِحَةَ وَلَمْ يُصَلِّ شَيْئًا حَتَّى أَصْبَحَ فَقَالَ ‏ ‏بَالَ الشَّيْطَانُ فِي أُذُنِهِ ‏ ‏قَالَ ‏ ‏يُونُسُ ‏ ‏قَالَ ‏ ‏الْحَسَنُ ‏ ‏إِنَّ بَوْلَهُ وَاللَّهِ ثَقِيلٌ ‏","","",""],[9152,9152,"","আমার বাবার চেয়ে বরং ঈশ্বর সম্বন্ধে আরও ভালো কিছু জানার চেষ্টা করা সম্বন্ধে আমরা কথা বলেছিলাম । আমার হৃদয়কে এটা ভুলে না যেতে বলা হয় ।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ رَجُلٍ يَأْخُذُ مِمَّا قَضَى اللَّهُ وَرَسُولُهُ كَلِمَةً أَوْ ثِنْتَيْنِ أَوْ ثَلَاثًا أَوْ أَرْبَعًا أَوْ خَمْسًا فَيَجْعَلُهُنَّ فِي طَرَفِ رِدَائِهِ فَيَعْمَلُ بِهِنَّ وَيُعَلِّمُهُنَّ قُلْتُ أَنَا وَبَسَطْتُ ثَوْبِي وَجَعَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحَدِّثُ حَتَّى انْقَضَى حَدِيثُهُ فَضَمَمْتُ ثَوْبِي إِلَى صَدْرِي فَأَنَا أَرْجُو أَنْ أَكُونَ لَمْ أَنْسَ حَدِيثًا سَمِعْتُهُ مِنْهُ ‏","","",""],[9153,9153,"","আমরা কথা বলেছি বড় হওয়ার চেয়ে বড় হওয়ার চেয়ে ভালো হতে হবে, কিন্তু কোন লোককে তার ভাইয়ের বিষ বলা যাবে না।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ عُبَيْدٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏يَسُمْ ‏ ‏الرَّجُلُ عَلَى ‏ ‏سَوْمِ ‏ ‏أَخِيهِ وَلَا يَخْطُبْ عَلَى خِطْبَةِ أَخِيهِ ‏","","",""],[9154,9154,"","আমরা তাকে দেখানোর সময় নিয়ে কথা বলেছি অথবা হয়তো আমি জানিনা কিভাবে বাবাকে সাহায্য করতে হয় সময় নষ্ট করে। আমি এটা থেকে আলো এর ফল খাই, যা আমি শুনেছি, ঈশ্বর তাদের কাছে প্রার্থনা করেছেন। ( প্রকা.","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ عَبْدِ اللَّهِ بْنِ قَارِظٍ ‏ ‏أَوْ ‏ ‏قَارَضٍ ‏ ‏لَا أَدْرِي شَكَّ ‏ ‏إِسْمَاعِيلُ ‏ ‏أَنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏أَكَلَ ‏ ‏أَثْوَارَ أَقِطٍ فَتَوَضَّأَ فَقَالَ أَتَدْرُونَ مِمَّا تَوَضَّأْتُ إِنِّي أَكَلْتُ ‏ ‏أَثْوَارَ أَقِطٍ فَتَوَضَّأْتُ مِنْهُ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏تَوَضَّئُوا مِمَّا مَسَّتْ النَّارُ ‏","","",""],[9155,9155,"","সেই সাক্ষি তার কাছে প্রার্থনা করেছেন এবং আত্মসমর্পণ করেছেন, যতক্ষণ না তিনি তার রক্তের ব্যথাকে শেষ করে দেবেন, ততক্ষণ পর্যন্ত তিনি তার রক্তকে শুকিয়ে দেবেন না । তুমি তাদেরকে দাস হিসেবে অথবা এক হাতে বলতে গেলে...","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ أَبِي زَيْنَبَ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏ذُكِرَ الشَّهِيدُ عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَا تَجِفُّ الْأَرْضُ مِنْ دَمِهِ حَتَّى ‏ ‏تَبْتَدِرَهُ ‏ ‏زَوْجَتَاهُ كَأَنَّهُمَا ‏ ‏ظِئْرَانِ ‏ ‏أَضَلَّتَا ‏ ‏فَصِيلَيْهِمَا ‏ ‏فِي ‏ ‏بَرَاحٍ ‏ ‏مِنْ الْأَرْضِ بِيَدِ ‏ ‏أَوْ قَالَ فِي يَدِ ‏ ‏كُلِّ وَاحِدَةٍ مِنْهُمَا ‏ ‏حُلَّةٌ ‏ ‏هِيَ خَيْرٌ مِنْ الدُّنْيَا وَمَا فِيهَا ‏","","",""],[9156,9156,"","আমরা ঈশ্বরের দোহাইে কথা বলেছি তিনি আমার বাবার কথা শুনে খুশি। তার টাকা আর টাকা দিয়ে মেয়েদের টাকা দিতে হবে। ঋণ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تُنْكَحُ النِّسَاءُ لِأَرْبَعٍ لِمَالِهَا وَجَمَالِهَا وَحَسَبِهَا وَدِينِهَا فَاظْفَرْ بِذَاتِ الدِّينِ ‏ ‏تَرِبَتْ ‏ ‏يَدَاكَ ‏","","",""],[9157,9157,"","আমরা এমন এক ছেলের কথা বলেছিলাম, যিনি আমার বাবার কথা শুনেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ يَسِيرُ فَلَعَنَ رَجُلٌ نَاقَةً فَقَالَ ‏ ‏أَيْنَ صَاحِبُ النَّاقَةِ فَقَالَ الرَّجُلُ أَنَا قَالَ أَخِّرْهَا فَقَدْ أُجِبْتَ فِيهَا ‏","","",""],[9158,9158,"","আমরা একটা ছেলের কথা বলেছিলাম যে সে আমার বাবার ব্যাপারে কথা বলেছে, তাকে বলে দিয়েছে যে আমি আমার নির্দেশ দিচ্ছি তুমি তাদের জিজ্ঞেস করার আগেই। কাজ শেষ, তারপর আমি আদেশ দিচ্ছি তুমি এটা থেকে পার হয়ে যাবে.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَرُونِي ‏ ‏مَا تَرَكْتُكُمْ فَإِنَّمَا هَلَكَ مَنْ كَانَ قَبْلَكُمْ بِكَثْرَةِ سُؤَالِهِمْ أَنْبِيَاءَهُمْ وَاخْتِلَافِهِمْ عَلَيْهِمْ وَإِذَا نَهَيْتُكُمْ عَنْ شَيْءٍ فَانْتَهُوا وَإِذَا أَمَرْتُكُمْ بِأَمْرٍ فَأْتُوا مِنْهُ مَا اسْتَطَعْتُمْ ‏","","",""],[9159,9159,"","আমরা একটি ছেলের কথা বলেছিলাম যে সে আমার বাবার কথা শুনেছে, তাকে বলল যে একজন মহিলা তার পা রক্ষা করতে সব সমস্যার সমাধান করবে আর তাকে ভেঙ্গে ফেলতে পারে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَرْأَةُ كَالضِّلَعِ فَإِنْ تَحْرِصْ عَلَى إِقَامَتِهِ تَكْسِرْهُ وَإِنْ تَتْرُكْهُ تَسْتَمْتِعْ بِهِ وَفِيهِ عِوَجٌ ‏","","",""],[9160,9160,"","আমরা আমার বাবার কথা বলেছিলাম, যে আমার বাবার কথা শুনেছে, সে বলেছিল, সে নাকি আমার বাবার কাছ থেকে চলে যাবে, সে আমার বাবার কাছ থেকে পালিয়ে যাবে, যে তোমার জন্য প্রার্থনা করেছে। বাড়ি তার গল্প মুছে ফেলেছে, তুমি তাকে হারিয়ে ফেলেছ, তোমার কোন অপরাধ নেই।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبَا الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْ أَنَّ رَجُلًا اطَّلَعَ عَلَيْكَ فِي بَيْتِكَ فَحَذَفْتَهُ بِحَصَاةٍ فَفَقَأْتَ عَيْنَهُ لَمْ يَكُنْ عَلَيْكَ ‏ ‏جُنَاحٌ ‏","","",""],[9161,9161,"","তারা যত বেশি জিজ্ঞেস করে, ততই তারা বলে যে, টাকা হচ্ছে এমন আর এখানে এটাই হল ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمُكْثِرُونَ هُمْ الْأَسْفَلُونَ إِلَّا مَنْ قَالَ بِالْمَالِ هَكَذَا وَهَكَذَا وَهَكَذَا وَهَكَذَا أَمَامَهُ وَعَنْ يَمِينِهِ وَعَنْ شِمَالِهِ وَخَلْفَهُ ‏","","",""],[9162,9162,"","আমরা একটা ছেলের কথা বলেছিলাম যে সে আমার বাবার কথা শুনেছে, তাকে বলেছে তুমি সিনেমা আর ট্রাফিকের ব্যাপারে কথা বলবে না যতক্ষণ না তুমি এই অবস্থা আর ট্রাফিকের মৃত্যু হতে পার।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى يُقْبَضَ الْعِلْمُ وَيَظْهَرَ الْجَهْلُ وَيَكْثُرَ الْهَرْجُ قِيلَ وَمَا الْهَرْجُ قَالَ الْقَتْلُ ‏","","",""],[9163,9163,"","আমরা একটা ছেলের কথা বলেছিলাম যে আমার বাবা দেবী হওয়ার কথা বলেছিলাম, তার নিজের ছেলের সাথে সব কথা বলতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو الزِّنَادِ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏كُلُّ ابْنِ ‏ ‏آدَمَ ‏ ‏يَبْلَى وَيَأْكُلُهُ التُّرَابُ إِلَّا عَجْبَ الذَّنَبِ مِنْهُ خُلِقَ وَفِيهِ يُرَكَّبُ ‏","","",""],[9164,9164,"","আমরা একটা ভালো মন তৈরি করতে পেরে খুশি হয়েছি যখন আমরা কিছু হারানোর জন্য, ঈশ্বর তাকে আমার ক্লাবে যেতে নিষেধ করেছেন, যাতে সে এই হতাশার মধ্যে সন্তুষ্ট না হয় হতাশ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ مَيْمُونٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عُثْمَانَ النَّهْدِيُّ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَهُ أَنْ يَخْرُجَ فَيُنَادِيَ أَنْ لَا صَلَاةَ إِلَّا بِقِرَاءَةِ ‏ ‏فَاتِحَةِ الْكِتَابِ ‏ ‏فَمَا زَادَ ‏","","",""],[9165,9165,"","আমরা বাবার ছেলেকে কবর থেকে দূরে যেতে সাহায্য করার চেষ্টা করেছি এবং তিনি যুক্তি দেখিয়েছেন যে আমার বাবা চলে গেছেন। আমার বাবা একজন পলাতক হিসেবে আমার বাবা খুশি যে, ঈশ্বর বলেছেন, ঈশ্বর প্রার্থনা করেছেন। তার জন্য এবং ঈশ্বর তাঁর ভালবাসার জন্য এসেছে। ওয়াদা কর, নাহলে এটা হবে অনেক বড় ব্যাপার, যখন সে শয়তানের থেকে এসেছে.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏الْمَقْبُرِيِّ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ يُحِبُّ الْعُطَاسَ وَيَكْرَهُ التَّثَاؤُبَ فَمَنْ عَطَسَ فَحَمِدَ اللَّهَ فَحَقٌّ عَلَى مَنْ سَمِعَهُ أَنْ يَقُولَ يَرْحَمُكَ اللَّهُ وَإِذَا تَثَاءَبَ أَحَدُكُمْ فَلْيَرُدَّهُ مَا اسْتَطَاعَ وَلَا يَقُلْ آهْ آهْ فَإِنَّ أَحَدَكُمْ إِذَا فَتَحَ فَاهُ فَإِنَّ الشَّيْطَانَ يَضْحَكُ مِنْهُ ‏ ‏أَوْ بِهِ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏فِي حَدِيثِهِ وَأَمَّا التَّثَاؤُبُ فَإِنَّمَا هُوَ مِنْ الشَّيْطَانِ ‏","","",""],[9166,9166,"","আমার বাবার সাথে আমরা কথা বলেছি যে ক্ষমার আগে আমার সাথে কথা হয়েছে একজন ভালো ছেলে, আমার বাবা তার কাছে ঈশ্বরের কাছে প্রার্থনা করেন যে তিনি প্রভুকে উদ্ধার করবেন প্রভুর কাছে ফিরে যাও।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مِهْرَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْأَبْعَدُ فَالْأَبْعَدُ مِنْ الْمَسْجِدِ أَعْظَمُ أَجْرًا ‏","","",""],[9167,9167,"","আমি বলেছিলাম যে, কীভাবে আমি সেই ভাববাদী ঈশ্বরের কাছে প্রার্থনা করতে শুনেছি, যিনি নিজেকে উৎসর্গ করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَجْلَانُ ‏ ‏مَوْلَى ‏ ‏الْمُشْمَعِلِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تُسَابَّ وَأَنْتَ صَائِمٌ وَإِنْ سَبَّكَ إِنْسَانٌ فَقُلْ إِنِّي صَائِمٌ ‏","","",""],[9168,9168,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং আমার আত্মার গৌরবে তিনি তা করবেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى يَعْنِي ابْنَ سَعِيدٍ ‏ ‏عَنْ ‏ ‏يَزِيْدَ بْنِ كَيْسَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو حَازِمٍ ‏ ‏قَالَ قَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏بَيْنَمَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْمَسْجِدِ إِذْ قَالَ يَا ‏ ‏عَائِشَةُ ‏ ‏نَاوِلِينِي الثَّوْبَ قَالَتْ إِنِّي لَسْتُ أُصَلِّي قَالَ إِنَّهُ لَيْسَ فِي يَدِكِ فَنَاوَلَتْهُ ‏","","",""],[9169,9169,"","আমরা একটি সুখী ছেলে কথা বলেছি যে আমার বাবার সাথে কথা বলেছে যে কিনা নগ্ন হয়ে গেছে, ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং তাকে আত্মসমর্পণ করবেন, তাই আমি তার আত্মা উদিত করব। যে তার লোক, সে আমাদের সেই শয়তান বানিয়েছে... ...সে বলেছে সে বলেছে সে বলেছে, \"হেতোর প্রার্থনা।\" এরপর প্রার্থনা দ্বারা মূল্যায়নকৃত","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ كَيْسَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏عَرَّسْنَا ‏ ‏مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمْ نَسْتَيْقِظْ حَتَّى طَلَعَتْ الشَّمْسُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِيَأْخُذْ كُلُّ رَجُلٍ بِرَأْسِ ‏ ‏رَاحِلَتِهِ ‏ ‏فَإِنَّ هَذَا مَنْزِلٌ حَضَرَنَا فِيهِ الشَّيْطَانُ قَالَ فَفَعَلْنَا قَالَ فَدَعَا بِالْمَاءِ فَتَوَضَّأَ ثُمَّ صَلَّى رَكْعَتَيْنِ قَبْلَ صَلَاةِ ‏ ‏الْغَدَاةِ ‏ ‏ثُمَّ أُقِيمَتْ الصَّلَاةُ فَصَلَّى ‏ ‏الْغَدَاةَ ‏","","",""],[9170,9170,"","ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং তাদের বাধা দেবেন, যাতে আমি আপনার ভয়কে সম্মান করি । বিষ থেকে তাকে বাঁচাতে কিছু করতে হবে, তোমার তিনটা গরু আছে আর সে তিন গরুই মূল্যবান।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ كَيْسَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏احْشُدُوا فَإِنِّي سَأَقْرَأُ عَلَيْكُمْ ثُلُثَ الْقُرْآنِ قَالَ فَحَشَدَ مَنْ حَشَدَ ثُمَّ خَرَجَ ‏ ‏فَقَرَأَ ‏ ‏قُلْ هُوَ اللَّهُ أَحَدٌ ‏ ‏ثُمَّ دَخَلَ فَقَالَ بَعْضُنَا لِبَعْضٍ هَذَا خَبَرٌ جَاءَهُ مِنْ السَّمَاءِ فَذَلِكَ الَّذِي أَدْخَلَهُ ثُمَّ خَرَجَ فَقَالَ إِنِّي قَدْ قُلْتُ لَكُمْ إِنِّي سَأَقْرَأُ عَلَيْكُمْ ثُلُثَ الْقُرْآنِ وَإِنَّهَا تَعْدِلُ ثُلُثَ الْقُرْآنِ ‏","","",""],[9171,9171,"","আমরা আমার বাবা কুমারী হয়ে এবং আমার সাথে যৌন সম্পর্ক করার কথা বলেছিলাম। সে কি জানে বা কে জানে সে কি বিশ্বাস করে সে যা করেছে তা সে হারিয়ে ফেলছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَوْفٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خِلَاسٌ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَالْحَسَنِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَتَى ‏ ‏كَاهِنًا ‏ ‏أَوْ عَرَّافًا فَصَدَّقَهُ بِمَا يَقُولُ فَقَدْ كَفَرَ بِمَا أُنْزِلَ عَلَى ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[9172,9172,"","আমরা দু'বার কথা বলেছি যে আমরা কতবার কথা বলেছি, ঈশ্বর তার জন্য প্রার্থনা করেছেন আর তিনি বলেছিলেন যদি তিনি এটা নিয়ে নেন বা যুদ্ধ করেন তাহলে তিনি আত্মসমর্পণ করবেন। যাওয়ার পর ফোন করেছিল।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْمُثَنَّى بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏بُشَيْرِ بْنِ كَعْبٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا اخْتَلَفْتُمْ أَوْ تَشَاجَرْتُمْ فِي الطَّرِيقِ فَدَعُوا ‏ ‏سَبْعَةَ ‏ ‏أَذْرُعٍ ‏","","",""],[9173,9173,"","আমরা এক ছেলে হিসেবে সুখী হওয়া সম্পর্কে কথা বলেছি যে একবার বলেছিল সে একজন দেবতাহীন মানুষ হওয়ার জন্য দৃঢ়প্রতিজ্ঞ ছিল। শান্তি আর কথা বলতে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏فُضَيْلِ بْنِ غَزْوَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى عَلَى رَجُلٍ تَرَكَ دِينَارَيْنِ ‏ ‏أَوْ ثَلَاثَةً ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَيَّتَانِ ‏ ‏أَوْ ثَلَاثَةٌ ‏","","",""],[9174,9174,"","আমার বাবার স্বপ্নের মধ্যে এটা হওয়ার স্বপ্ন আমার বাবার দ্বারা বাপ্তাইজিত হওয়ার কথা আমরা বলেছিলাম। প্রত্যেক মাতালই একটা যুদ্ধ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كُلُّ مُسْكِرٍ حَرَامٌ ‏","","",""],[9175,9175,"","আমরা ইশ্বরের সাথে কথা বলেছি, আমার বাবা আর আমি আর আমার বাবার সাথে কথা বলেছি, আমার বাবার ছেলে বলেছে যে সে আমার সাথে কথা বলেছে যে একটা ছেলে যে খুনি। ঈশ্বরের ইচ্ছা ছিল, আমি আর আমার বাবার কথা বলেছি। ( গীত.","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏وَيَحْيَى بْنُ مَعِينٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدٍ يَعْنِي ابْنَ أَبِي هِنْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏إِسْمَاعِيلُ بْنُ أَبِي حَكِيمٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ ابْنِ مَرْجَانَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَعْتَقَ رَقَبَةً أَعْتَقَ اللَّهُ بِكُلِّ ‏ ‏إِرْبٍ ‏ ‏مِنْهَا ‏ ‏إِرْبًا ‏ ‏مِنْهُ مِنْ النَّارِ ‏","","",""],[9176,9176,"","আমরা বাবার সাথে কথা বলার চেষ্টা করে কথা বলেছিলাম, আর তারপর সে বললো, \"আমি আমার বাবাকে ভালবাসি।\" বাবা প্রভুর প্রভুর প্রভুর প্রভুর প্রভুর নিকট থেকে শুনেছি। তিনি মনে করেন, তিনি প্রত্যেকটি ডাক্তার আর মানুষ যিনি প্রার্থনা দেখছেন তিনি পঞ্চমজন আর একটি ভাল আত্মা আর তিনি তার ক্ষমতা অর্জন করতে পারেন।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُوسَى بْنُ أَبِي عُثْمَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو يَحْيَى ‏ ‏مَوْلَى ‏ ‏جَعْدَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏أَنَّهُ سَمِعَ مِنْ فَمِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْمُؤَذِّنُ يُغْفَرُ لَهُ ‏ ‏مَدَّ ‏ ‏صَوْتِهِ وَيَشْهَدُ لَهُ كُلُّ رَطْبٍ وَيَابِسٍ وَشَاهِدُ الصَّلَاةِ يُكْتَبُ لَهُ خَمْسٌ وَعِشْرُونَ حَسَنَةً وَيُكَفَّرُ عَنْهُ مَا بَيْنَهُمَا ‏","","",""],[9177,9177,"","আমরা জীবন্ত কথা বলেছি এবং এটা একটা সুখী ছেলে যে আমরা বলেছিলাম যখন আমরা বলেছিলাম তিনি বলেছেন তিনি তার জন্য প্রার্থনা করেছেন, আর তার প্রতি আশ্বস্ত করেছেন রাতে থেকে শুরু করে সমস্ত স্বপ্নের মধ্যে ঈশ্বর বলেছেন, মৃত্যু আমাদের কাছে একটা পবিত্র জায়গা তৈরি করে আমাদের কাছে ঘটেছে ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى وَهُوَ ابْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَيْكُمْ بِهَذِهِ الْحَبَّةِ السَّوْدَاءِ فَإِنَّ فِيهَا شِفَاءً مِنْ كُلِّ دَاءٍ إِلَّا السَّامَ قِيلَ يَا رَسُولَ اللَّهِ وَمَا السَّامُ قَالَ الْمَوْتُ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏وَيَعْلَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏مِثْلَهُ فِي الْحَبَّةِ السَّوْدَاءِ ‏","","",""],[9178,9178,"","আমার বাবার সঙ্গে একজন অজ্ঞান ছেলে হিসেবে কথা বলার সময় আমরা এক অজ্ঞান ছেলের কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏وَجَدَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رِيحَ ثُومٍ فِي الْمَسْجِدِ فَقَالَ ‏ ‏مَنْ أَكَلَ مِنْ هَذِهِ الشَّجَرَةِ الْخَبِيثَةِ فَلَا يَقْرَبَنَّ مَسْجِدَنَا ‏","","",""],[9179,9179,"","আমরা বাবার ছেলের কথা বলেছি, যারা ঈশ্বরকে ভয় করে না, তাদের দুর্বল হওয়ার জন্য এক ভয়ানক শাস্তি। ঈশ্বর তার জন্য প্রার্থনা করেন এবং তিনি আমার কাছে ফিরে গিয়ে আমাকে আত্মসমর্পণ করবেন। তার বাবামা তাকে একমাত্র পুরস্কারই দিয়েছিল ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏النَّضْرِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏بَشِيرِ بْنِ نَهِيكٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْعُمْرَى ‏ ‏مِيرَاثٌ لِأَهْلِهَا ‏ ‏أَوْ جَائِزَةٌ لِأَهْلِهَا ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[9180,9180,"","আমার কাছে দুই ডজন বই আছে, সবাই বলে আমরা একজন ভাববাদী।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عَوْفٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خِلَاسٌ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَيْنَ يَدَيْ السَّاعَةِ قَرِيبٌ مِنْ ثَلَاثِينَ دَجَّالِينَ كَذَّابِينَ كُلُّهُمْ يَقُولُ أَنَا نَبِيٌّ أَنَا نَبِيٌّ ‏","","",""],[9181,9181,"","আমি তাদেরকে একটা মই অথবা আমার মাকে আপনার দুঃখ দিয়ে পার করে দিতে চাই ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي لَأَمَرْتُهُمْ بِالسِّوَاكِ عِنْدَ كُلِّ صَلَاةٍ ‏ ‏أَوْ مَعَ كُلِّ صَلَاةٍ ‏","","",""],[9182,9182,"","আমরা একটি ভাল ছেলে বানান যে আমাকে ঈশ্বরের সাথে কথা বলেছে, কিন্তু আমার বাবা ছিল একটা বদমায়েশ, সে একদিন একবার বাবার কাছে যেতে যাচ্ছিল। আমি একজন মহান পিতা, যিনি এই বিষয়ে পড়তেন, আমার ভালোবাসা হচ্ছে যাজকের বাবা তার কাছে প্রার্থনা করে আত্মসমর্পণ করে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي رَافِعٍ ‏ ‏وَكَانَ كَاتِبًا ‏ ‏لِعَلِيٍّ ‏ ‏قَالَ كَانَ ‏ ‏مَرْوَانُ ‏ ‏يَسْتَخْلِفُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏عَلَى ‏ ‏الْمَدِينَةِ ‏ ‏فَاسْتَخْلَفَهُ مَرَّةً فَصَلَّى الْجُمُعَةَ فَقَرَأَ سُورَةَ ‏ ‏الْجُمُعَةِ ‏ ‏وَإِذَا جَاءَكَ الْمُنَافِقُونَ ‏ ‏فَلَمَّا انْصَرَفَ مَشَيْتُ إِلَى جَنْبِهِ فَقُلْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏قَرَأْتَ بِسُورَتَيْنِ قَرَأَ بِهِمَا ‏ ‏عَلِيٌّ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏قَالَ ‏ ‏قَرَأَ بِهِمَا حِبِّي ‏ ‏أَبُو الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[9183,9183,"","সেই সময় আমি আমার বাবার সঙ্গে কথা বলেছিলাম, যিনি বলেছিলেন যে, তিনি অজ্ঞান ছিলেন । কবর দেওয়া হয়েছিল যে, সে দুর্গে ফিরে আসবে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ اتَّبَعَ جَنَازَةَ مُسْلِمٍ إِيمَانًا ‏ ‏وَاحْتِسَابًا ‏ ‏فَصَلَّى عَلَيْهَا وَأَقَامَ حَتَّى تُدْفَنَ رَجَعَ ‏ ‏بِقِيرَاطَيْنِ ‏ ‏مِنْ الْأَجْرِ كُلُّ ‏ ‏قِيرَاطٍ ‏ ‏مِثْلُ ‏ ‏أُحُدٍ ‏ ‏وَمَنْ صَلَّى عَلَيْهَا وَرَجَعَ قَبْلَ أَنْ تُدْفَنَ فَإِنَّهُ يَرْجِعُ ‏ ‏بِقِيرَاطٍ ‏","","",""],[9184,9184,"","আমরা আমার বাবার সঙ্গে এক ছেলে হিসেবে কথা বলেছিলাম, যার সঙ্গে তার শান্তি ছিল ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عَوْفٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خِلَاسٌ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَثَلُ الَّذِي ‏ ‏يَعُودُ ‏ ‏فِي هِبَتِهِ مَثَلُ الْكَلْبِ إِذَا شَبِعَ ‏ ‏قَاءَ ‏ ‏ثُمَّ عَادَ فِي ‏ ‏قَيْئِهِ ‏","","",""],[9185,9185,"","আমরা রূপকের রূপক কথা বলেছিলাম, যা আমরা একটা নির্দিষ্ট মূল্যের প্রথা তৈরি করেছি । আর আমি আমার মায়ের মৃত্যুর জন্য ঈশ্বরের প্রবল ইচ্ছাকে আমার মায়ের কাছে বলতে চাই, কুত্তার বাচ্চা।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏وَمُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏غُنْدَرٌ ‏ ‏فِي حَدِيثِهِ قَالَ ‏ ‏سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّ ‏ ‏لِكُلِّ نَبِيٍّ دَعْوَةً ‏ ‏دَعَاهَا ‏ ‏وَإِنِّي أُرِيدُ أَنْ أَدَّخِرَ دَعْوَتِي إِنْ شَاءَ اللَّهُ شَفَاعَةً لِأُمَّتِي يَوْمَ الْقِيَامَةِ ‏ ‏قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏فِي أُمَّتِهِ ‏","","",""],[9186,9186,"","আমরা একটা দাঙ্গার কথা বলেছিলাম যেটা আমাদের সাথে একটা টোপের টোপের মত হয়েছিল. আগুন থেকে ধরায় রাত পার হয়ে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ زِيَادٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏يَمُرُّ بِنَا وَنَحْنُ نَتَوَضَّأُ مِنْ الْمَطْهَرَةِ فَيَقُولُ لَنَا ‏ ‏أَسْبِغُوا ‏ ‏الْوُضُوءَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏وَيْلٌ ‏ ‏لِلْأَعْقَابِ ‏ ‏مِنْ النَّارِ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏الْعَقِبِ ‏","","",""],[9187,9187,"","বাবা একজন মরুভূমিবাসী যিনি তার লোকেদের দর্শনীয় বাক্যগুলোর বিষয়ে খুঁজতে আঘাত করবেন, তিনি হলেন দর্শনীয় ঈশ্বরের কাছে প্রার্থনা করেছিলেন । আর সে নিজেকে আত্মসমর্পণ করবে তার বাটনকে না দেখাতে.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏إِنْ شَاءَ اللَّهُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ زِيَادٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏مَرْوَانُ ‏ ‏يَسْتَخْلِفُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏عَلَى ‏ ‏الْمَدِينَةِ ‏ ‏فَيَضْرِبُ بِرِجْلِهِ فَيَقُولُ خَلُّوا الطَّرِيقَ خَلُّوا قَدْ جَاءَ الْأَمِيرُ قَدْ جَاءَ الْأَمِيرُ قَالَ ‏ ‏أَبُو الْقَاسِمِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَنْظُرُ اللَّهُ إِلَى مَنْ جَرَّ ‏ ‏إِزَارَهُ ‏ ‏بَطَرًا ‏","","",""],[9188,9188,"","আমি আমার বাবার সাথে কথা বলতে পেরে খুশি হয়েছি, সে খুব দ্রুত তাকে দেখতে চায় আর আমি ভাবছি তার ক্লাসে তাকে দেখতে, তারপর সে ৩টা করে ফেলবে সেকেন্ড।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏صُومُوا لِرُؤْيَتِهِ وَأَفْطِرُوا لِرُؤْيَتِهِ فَإِنْ ‏ ‏غُمَّ ‏ ‏عَلَيْكُمْ فَأَكْمِلُوا ‏ ‏الْعِدَّةَ ‏ ‏ثَلَاثِينَ ‏","","",""],[9189,9189,"","আমরা কথা বলেছিলাম, কীভাবে সে আমার ছেলের স্বপ্নের কথা বলতে চেষ্টা করেছিল। তারা তাকে দেখতে এসেছিল এবং আমি তাকে দেখতে চেয়েছিলাম যদি তারা তিন সেকেন্ড করে থাকে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏صُومُوا لِرُؤْيَتِهِ وَأَفْطِرُوا لِرُؤْيَتِهِ فَإِنْ ‏ ‏غُمَّ ‏ ‏عَلَيْكُمْ فَأَكْمِلُوا ‏ ‏الْعِدَّةَ ‏ ‏ثَلَاثِينَ ‏","","",""],[9190,9190,"","আমরা খেলার ব্যাপারে খুশি হয়েছি, আমরা আমার সুন্দর চোখওয়ালা ছেলে ও দু:খের প্রেমিকের জন্য একটা দুঃখের ছেলে। সে একটা ভালো ছেলে ছিল, যে বাবাকে বলতে চেয়েছিল যে তার একটা ছিলো মহান স্বপ্ন ছিল তার একটা মহান স্বপ্ন ছিল, তুমি আমার সাথে শুরু করতে পারতে আর তারপর তুমি ভুল করে ফেল।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَحْفِهِمَا جَمِيعًا أَوْ انْعَلْهُمَا جَمِيعًا فَإِذَا انْتَعَلْتَ فَابْدَأْ بِالْيُمْنَى وَإِذَا خَلَعْتَ فَابْدَأْ بِالْيُسْرَى ‏","","",""],[9191,9191,"","আমরা একটা গেমের কথা বলেছিলাম যেটা আমাদের সাথে হয়েছিল, কিন্তু আমরা আমার ছেলেকে সাহায্য করার চেষ্টা করেছিলাম, একজন পলাতক, যে তাকে খুন করার চেষ্টা করেছিল। তার সাথে বসে বসে আছে, সে তার সাথে বসে না, সে খাচ্ছে বা খাচ্ছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا جَاءَ خَادِمُ أَحَدِكُمْ بِطَعَامِهِ فَلْيُجْلِسْهُ مَعَهُ فَإِنْ لَمْ يُجْلِسْهُ مَعَهُ فَلْيُنَاوِلْهُ أُكْلَةً أَوْ أُكْلَتَيْنِ فَإِنَّهُ ‏ ‏وَلِيَ ‏ ‏عِلَاجَهُ ‏ ‏وَحَرَّهُ ‏","","",""],[9192,9192,"","আমরা বলেছিলাম, কীভাবে সে আমার ছেলের স্বপ্নের কথা বলতে চেষ্টা করলো। সে বলল, যে রোগী কিনেছিল, সে সকালেই তার সাথে হেঁটে পালিয়ে গিয়েছিল।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ اشْتَرَى شَاةً ‏ ‏مُصَرَّاةً ‏ ‏فَرَدَّهَا رَدَّ مَعَهَا ‏ ‏صَاعًا ‏ ‏مِنْ تَمْرٍ لَا ‏ ‏سَمْرَاءَ ‏","","",""],[9193,9193,"","আমরা একটা গেমের কথা বলেছিলাম, তিনি আমাকে বলেছেন যে তিনি আমার বাবার মূল্য দিয়েছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَطَاءُ بْنُ أَبِي مَيْمُونَةَ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏كَانَ اسْمُ ‏ ‏زَيْنَبَ ‏ ‏بَرَّةَ ‏ ‏فَسَمَّاهَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَيْنَبَ ‏","","",""],[9194,9194,"","আমরা দুটো জাহাজের কথা বলেছিলাম, যে আমার ভাই বিছানায় ফিরে যাবে আর চলে যাবে। আমরা একটা শিকারীর অভুক্ত ছেলেকে নিয়ে কথা বলেছি। যে বলে বাবা একটা ভালো ছেলে। আমি শুনেছি, বাবা আমার বাবা খুব ভালো ছেলে। আমি তাকে বলেছিলাম, আমি আমার কথা বলেছি। আমি যখন বলেছিলাম, আমি বলেছিলাম, আমি আমার ভাই আবার আমার ভাই বিছানায় ফিরে যেতে চাই, তখন আমি আমার ভাই আবার ঘুমাতে যাব। আমি বলেছিলাম, আমি বলেছিলাম, আমি আমার ভাই আবার আমার ভাই বিছানায় ফিরে যেতে চাই। আমি যখন আমি বলেছিলাম, আমি বলেছিলাম, আমি আমার ভাই আবার আমার ভাই আবার ঘুমাতে যেতে চাই, আমি যখন আমি তাকে বলেছিলাম, আমি বলেছিলাম, আমি বলেছিলাম, আমি বলেছিলাম, আমি আমার ভাই আবার আমার ভাই আবার আমার ছেলের কথা বলছি, আমি আমার ছেলের সাথে ঘুম থেকে চলে যাব। আমি বলেছিলাম, আমি আমার বাবা আমার ছেলে। আমি বলেছিলাম, আমি আমার বাবা আমার বাবা খুবই ভালো একজন মানুষ। ( খ) কেন আমাদের ঈশ্বরের প্রতি অনুগত থাকতে হবে?","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعْدُ بْنُ إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَعْرَجِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَحْفَظُهُ قَالَ إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَقْرَأُ فِي صَلَاةِ الصُّبْحِ يَوْمَ الْجُمُعَةِ ‏ ‏الم تَنْزِيلُ ‏ ‏وَهَلْ أَتَى ‏","","",""],[9195,9195,"","আমরা বাবার সাথে কথা বলার সময় বাবার সাহায্য করার চেষ্টা করেছি। আর তাকে প্রভুর আশীর্বাদে গুলি করো।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدِ بْنِ أَبِي هِنْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ أَبِي حَكِيمٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ ابْنِ مَرْجَانَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَعْتَقَ رَقَبَةً أَعْتَقَ اللَّهُ بِكُلِّ ‏ ‏إِرْبٍ ‏ ‏مِنْهُ ‏ ‏إِرْبًا ‏ ‏مِنْ النَّارِ ‏","","",""],[9196,9196,"","আমার বাবার ছেলে বাবার ইচ্ছা সম্পর্কে কথা বলতে আমার সাথে কথা বলবে। ঈশ্বর তার জন্য প্রার্থনা করেন এবং তিনি ঈশ্বরের কাছে সব শ্বাস-প্রশ্বাস প্রদান করেন। সময়.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏خَالِي ‏ ‏الْحَارِثُ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَتَبَ اللَّهُ عَلَى كُلِّ نَفْسٍ حَظَّهَا مِنْ الزِّنَا ‏","","",""],[9197,9197,"","আমরা আমার ছেলে দেবীর গল্প বলেছিলাম, তিনি বললেন অতিথিরা তিনজন, আর সে এখনো বন্ধু হবে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الضِّيَافَةَ ثَلَاثَةٌ فَمَا زَادَ فَهُوَ ‏ ‏صَدَقَةٌ ‏","","",""],[9198,9198,"","আমরা একটা ছেলের কথা বলেছিলাম যে সে আমার সাথে কথা বলেছে, সে তার শান্তির কিছু কথা ভুলে যাবে, ভালো কারণ বিশ্বাস করে, আর স্বর্গে যেতে পারবে না। ( পড়ুন, গীতসংহিতা ৩৭: ১১.)","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ مُسْلِمٍ يَتَصَدَّقُ ‏ ‏بِصَدَقَةٍ ‏ ‏مِنْ كَسْبٍ ‏ ‏طَيِّبٍ ‏ ‏وَلَا يَصْعَدُ إِلَى السَّمَاءِ إِلَّا ‏ ‏طَيِّبٌ ‏ ‏إِلَّا كَأَنَّمَا يَضَعُهَا فِي كَفِّ الرَّحْمَنِ عَزَّ وَجَلَّ ‏ ‏فَيُرَبِّيهَا كَمَا يُرَبِّي الرَّجُلُ ‏ ‏فَلُوَّهُ ‏ ‏أَوْ ‏ ‏فَصِيلَهُ ‏ ‏حَتَّى إِنَّ التَّمْرَةَ لَتَعُودُ مِثْلَ الْجَبَلِ الْعَظِيمِ ‏","","",""],[9199,9199,"","আমরা পুরো বিশ্ব সম্পর্কে কথা বলেছি, আমরা আমার বাবার প্রধান সম্পাদকের কথা বলেছিলাম, যে তাকে বলেছিল যে সে সেই নয় সেই ব্যক্তি যে কিনা এই ব্যক্তি যে কিনা তাকে বলেছিল যে তিনিই সেই ব্যক্তি যিনি ছিলেন। সে ছিল সেই লোক যে কিনা সে, ঈশ্বর তাকে বলেছেন যে সে মানুষের সাথে যুদ্ধ করবে না যতক্ষণ না পর্যন্ত না পর্যন্ত তারা বলে যে এটাই তার আগের কথা।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُجَالِدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَامِرٌ ‏ ‏عَنِ ‏ ‏الْمُحَرِّرِ بْنِ أَبِي هُرَيْرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَزَالُ النَّاسُ يَسْأَلُونَ حَتَّى يَقُولُوا كَانَ اللَّهُ قَبْلَ كُلِّ شَيْءٍ فَمَا كَانَ قَبْلَهُ ‏","","",""],[9200,9200,"","আমি শপথ করে বলছি যে, যাজক তার কাছে প্রার্থনা করেছেন এবং তিনি বলবেন যে, কে তার প্রভুর কথা বলেছে । তিনি যা বলেছিলেন তার জন্য দোষারোপ করা উচিত নয়।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏فُضَيْلِ بْنِ غَزْوَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي نُعْمٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْقَاسِمِ ‏ ‏نَبِيُّ التَّوْبَةِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ ‏ ‏قَذَفَ ‏ ‏مَمْلُوكَهُ بَرِيئًا مِمَّا قَالَ لَهُ إِلَّا قَامَ عَلَيْهِ ‏ ‏يَعْنِي ‏ ‏الْحَدَّ ‏ ‏يَوْمَ الْقِيَامَةِ إِلَّا أَنْ يَكُونَ كَمَا قَالَ ‏","","",""]];
